    { const char * tb_v2824 = "// переключение задач: запомнить кадр и «переменные потока» текущей, отдать кадр следующей\n"; *(const char * *)tb_grow(v_lines) = tb_v2824; }
    { const char * tb_v2825 = "TB_API uint64_t *tb_schedule(uint64_t *frame) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2825; }
