    { const char * tb_v3052 = "    for (uint64_t t = 0; t < low >> 21; t++) tb_pdir[0][t] = (uint64_t)(uintptr_t)tb_pt[t] | 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v3052; }
