    { const char * tb_v3143 = "            tb_free0(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v3143; }
    { const char * tb_v3144 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3144; }
    { const char * tb_v3145 = "        at = next;\n"; *(const char * *)tb_grow(v_lines) = tb_v3145; }
    { const char * tb_v3146 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3146; }
    { const char * tb_v3147 = "    tb_irq_restore(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v3147; }
    { const char * tb_v3148 = "    return got;\n"; *(const char * *)tb_grow(v_lines) = tb_v3148; }
    { const char * tb_v3149 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3149; }
