    { const char * tb_v3185 = "    tb_panic(what, v == 14 || v == 8 ? a : v, rip);\n"; *(const char * *)tb_grow(v_lines) = tb_v3185; }
    { const char * tb_v3186 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3186; }
    { const char * tb_v3187 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3187; }
    { const char * tb_v3188 = "// все прерывания приходят сюда; ответ — кадр, в который вернуться (так переключаются задачи)\n"; *(const char * *)tb_grow(v_lines) = tb_v3188; }
    { const char * tb_v3189 = "__attribute__((used)) static uint64_t *tb_isr(uint64_t *f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3189; }
    { const char * tb_v3190 = "    uint64_t v = f[TB_F_VEC];\n"; *(const char * *)tb_grow(v_lines) = tb_v3190; }
    { const char * tb_v3191 = "    if (v < 32) return tb_fault(v, f);\n"; *(const char * *)tb_grow(v_lines) = tb_v3191; }
    { const char * tb_v3192 = "    if (v == 48) return tb_schedule(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v3192; }
    { const char * tb_v3193 = "    if (v == 49) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3193; }
    { const char * tb_v3194 = "        // таймер своего ядра процессора (APIC): 1000 раз в секунду\n"; *(const char * *)tb_grow(v_lines) = tb_v3194; }
    { const char * tb_v3195 = "        tb_lapic_w(0xB0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3195; }
    { const char * tb_v3196 = "        if (--tb_me()->slice <= 0) return tb_schedule(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v3196; }
