    { const char * tb_v3198 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3198; }
    { const char * tb_v3199 = "    int irq = (int)v - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v3199; }
    { const char * tb_v3200 = "    if (irq == 0) tb_ms++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3200; }
    { const char * tb_v3201 = "    if (irq == 1) tb_key_irq();\n"; *(const char * *)tb_grow(v_lines) = tb_v3201; }
    { const char * tb_v3202 = "    if (tb_irq_fn[irq]) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3202; }
    { const char * tb_v3203 = "        // своя функция прерывания: со своими «переменными потока»\n"; *(const char * *)tb_grow(v_lines) = tb_v3203; }
    { const char * tb_v3204 = "        tb_cpu *c = tb_me();\n"; *(const char * *)tb_grow(v_lines) = tb_v3204; }
    { const char * tb_v3205 = "        tb_set_fs(tb_tls_tp(c->irq_tls));\n"; *(const char * *)tb_grow(v_lines) = tb_v3205; }
