    { const char * tb_v3207 = "        tb_set_fs(tb_tls_tp(c->run >= 0 ? tb_slots[c->run].tls : c->irq_tls));\n"; *(const char * *)tb_grow(v_lines) = tb_v3207; }
    { const char * tb_v3208 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3208; }
    { const char * tb_v3209 = "    if (irq >= 8) tb_outb(0xA0, 0x20);\n"; *(const char * *)tb_grow(v_lines) = tb_v3209; }
    { const char * tb_v3210 = "    tb_outb(0x20, 0x20);\n"; *(const char * *)tb_grow(v_lines) = tb_v3210; }
