    { const char * tb_v3220 = "// загрузка: заголовок multiboot (флаг 2: «скажи, сколько памяти»). _start работает ещё в 32 битах:\n"; *(const char * *)tb_grow(v_lines) = tb_v3220; }
    { const char * tb_v3221 = "// строит таблицы страниц на первые 4 ГБ, включает режим 64 бит и прыгает в tb_kstart\n"; *(const char * *)tb_grow(v_lines) = tb_v3221; }
    { const char * tb_v3222 = "__attribute__((section(\".multiboot\"), used, aligned(4)))\n"; *(const char * *)tb_grow(v_lines) = tb_v3222; }
