    { const char * tb_v3224 = "// TSS ядра процессора i: ist1 — его стек для двойной ошибки\n"; *(const char * *)tb_grow(v_lines) = tb_v3224; }
    { const char * tb_v3225 = "TB_API void tb_tss_make(int i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3225; }
