    { const char * tb_v3235 = "    __asm__ volatile(\"wrmsr\" : : \"c\"(0xC0000101u), \"a\"((uint32_t)v), \"d\"((uint32_t)(v >> 32)) : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3235; }
    { const char * tb_v3236 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3236; }
