    { const char * tb_v3238 = "__attribute__((noreturn)) TB_API void tb_idle(void) { for (;;) __asm__ volatile(\"sti\\nhlt\"); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3238; }
    { const char * tb_v3239 = "// запись ядра процессора: стек и кадр пустого хода, переменные потока для прерываний\n"; *(const char * *)tb_grow(v_lines) = tb_v3239; }
    { const char * tb_v3240 = "TB_API void tb_cpu_init(tb_cpu *c, int id) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3240; }
    { const char * tb_v3241 = "    c->self = c; c->id = id; c->run = -1; c->slice = 10; c->prev = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3241; }
    { const char * tb_v3242 = "    unsigned char *tp = tb_tls_fresh(c->irq_tls);\n"; *(const char * *)tb_grow(v_lines) = tb_v3242; }
    { const char * tb_v3243 = "    *(int *)(tp - ((unsigned char *)tb_tls_self() - (unsigned char *)&tb_in_irq)) = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3243; }
