    { const char * tb_v3250 = "    fr[TB_F_RIP + 3] = (uint64_t)(uintptr_t)(top - 8); fr[TB_F_RIP + 4] = 0x10;\n"; *(const char * *)tb_grow(v_lines) = tb_v3250; }
