    { const char * tb_v3253 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3253; }
    { const char * tb_v3254 = "// --- несколько ядер процессора («звёзды») ---\n"; *(const char * *)tb_grow(v_lines) = tb_v3254; }
    { const char * tb_v3255 = "// Какие ядра есть — из таблицы ACPI «APIC» (MADT). Каждое будим так: INIT, потом дважды\n"; *(const char * *)tb_grow(v_lines) = tb_v3255; }
    { const char * tb_v3256 = "// SIPI с адресом 0x8000; там маленький код (ниже) переводит ядро из 16 бит сразу в 64\n"; *(const char * *)tb_grow(v_lines) = tb_v3256; }
    { const char * tb_v3257 = "// и прыгает в tb_ap_main со своим стеком.\n"; *(const char * *)tb_grow(v_lines) = tb_v3257; }
    { const char * tb_v3258 = "TB_API int tb_apic_ids[TB_NCPU];\n"; *(const char * *)tb_grow(v_lines) = tb_v3258; }
    { const char * tb_v3259 = "// таблицы ACPI лежат выше памяти, которую назвал загрузчик: показываем их кусок 2 МБ (только читать)\n"; *(const char * *)tb_grow(v_lines) = tb_v3259; }
    { const char * tb_v3260 = "TB_API void tb_map_2m(uint64_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3260; }
    { const char * tb_v3261 = "    if (a >= (4ull << 30) || a < (uint64_t)(uintptr_t)tb_heap_area) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3261; }
    { const char * tb_v3262 = "    uint64_t *e = &tb_pdir[a >> 30][(a >> 21) & 511];\n"; *(const char * *)tb_grow(v_lines) = tb_v3262; }
    { const char * tb_v3263 = "    if (*e) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3263; }
    { const char * tb_v3264 = "    tb_pdpt[a >> 30] = (uint64_t)(uintptr_t)tb_pdir[a >> 30] | 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v3264; }
    { const char * tb_v3265 = "    *e = (a & ~0x1FFFFFull) | 0x81;\n"; *(const char * *)tb_grow(v_lines) = tb_v3265; }
    { const char * tb_v3266 = "    __asm__ volatile(\"invlpg (%0)\" : : \"r\"(a) : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3266; }
    { const char * tb_v3267 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3267; }
    { const char * tb_v3268 = "TB_API int tb_find_cpus(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3268; }
    { const char * tb_v3269 = "    unsigned char *rsdp = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3269; }
    { const char * tb_v3270 = "    for (uint64_t a = 0xE0000; a < 0x100000 && !rsdp; a += 16)\n"; *(const char * *)tb_grow(v_lines) = tb_v3270; }
