    { const char * tb_v3545 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3545; }
    { const char * tb_v3546 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3546; }
    { const char * tb_v3547 = "// getenv в UTF-8; ответ живёт до конца программы (их мало и они короткие).\n"; *(const char * *)tb_grow(v_lines) = tb_v3547; }
    { const char * tb_v3548 = "// HOME на Windows обычно нет: тогда это USERPROFILE (C:\\Users\\имя)\n"; *(const char * *)tb_grow(v_lines) = tb_v3548; }
    { const char * tb_v3549 = "TB_API char *tb_win_getenv(const char *name) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3549; }
    { const char * tb_v3550 = "    wchar_t *n = tb_wide(name);\n"; *(const char * *)tb_grow(v_lines) = tb_v3550; }
    { const char * tb_v3551 = "    const wchar_t *v = n ? _wgetenv(n) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3551; }
    { const char * tb_v3552 = "    if (!v && strcmp(name, \"HOME\") == 0) v = _wgetenv(L\"USERPROFILE\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3552; }
    { const char * tb_v3553 = "    free(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3553; }
    { const char * tb_v3554 = "    return v ? tb_narrow(v) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3554; }
    { const char * tb_v3555 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3555; }
    { const char * tb_v3556 = "// cmd.exe /c убирает первую и последнюю кавычку, если кавычек больше двух:\n"; *(const char * *)tb_grow(v_lines) = tb_v3556; }
    { const char * tb_v3557 = "// поэтому команда целиком берётся ещё в одни кавычки\n"; *(const char * *)tb_grow(v_lines) = tb_v3557; }
    { const char * tb_v3558 = "TB_API wchar_t *tb_win_cmd(const char *command) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3558; }
    { const char * tb_v3559 = "    size_t n = strlen(command);\n"; *(const char * *)tb_grow(v_lines) = tb_v3559; }
    { const char * tb_v3560 = "    char *q = malloc(n + 3);\n"; *(const char * *)tb_grow(v_lines) = tb_v3560; }
    { const char * tb_v3561 = "    if (!q) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3561; }
    { const char * tb_v3562 = "    q[0] = '\"'; memcpy(q + 1, command, n); q[n + 1] = '\"'; q[n + 2] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3562; }
    { const char * tb_v3563 = "    wchar_t *w = tb_wide(q);\n"; *(const char * *)tb_grow(v_lines) = tb_v3563; }
    { const char * tb_v3564 = "    free(q);\n"; *(const char * *)tb_grow(v_lines) = tb_v3564; }
    { const char * tb_v3565 = "    return w;\n"; *(const char * *)tb_grow(v_lines) = tb_v3565; }
    { const char * tb_v3566 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3566; }
    { const char * tb_v3567 = "TB_API int tb_win_system(const char *command) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3567; }
    { const char * tb_v3568 = "    wchar_t *c = tb_win_cmd(command);\n"; *(const char * *)tb_grow(v_lines) = tb_v3568; }
    { const char * tb_v3569 = "    int r = c ? _wsystem(c) : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3569; }
    { const char * tb_v3570 = "    free(c);\n"; *(const char * *)tb_grow(v_lines) = tb_v3570; }
    { const char * tb_v3571 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v3571; }
    { const char * tb_v3572 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3572; }
    { const char * tb_v3573 = "TB_API FILE *tb_win_popen(const char *command, const char *mode) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3573; }
    { const char * tb_v3574 = "    wchar_t *c = tb_win_cmd(command), *m = tb_wide(mode);\n"; *(const char * *)tb_grow(v_lines) = tb_v3574; }
    { const char * tb_v3575 = "    FILE *f = c && m ? _wpopen(c, m) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3575; }
    { const char * tb_v3576 = "    free(c); free(m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3576; }
    { const char * tb_v3577 = "    return f;\n"; *(const char * *)tb_grow(v_lines) = tb_v3577; }
    { const char * tb_v3578 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3578; }
    { const char * tb_v3579 = "// папка: _wopendir / _wreaddir, имена — в UTF-8\n"; *(const char * *)tb_grow(v_lines) = tb_v3579; }
    { const char * tb_v3580 = "struct tb_win_dirent { char d_name[MAX_PATH * 4]; };\n"; *(const char * *)tb_grow(v_lines) = tb_v3580; }
    { const char * tb_v3581 = "typedef struct { _WDIR *d; struct tb_win_dirent e; } tb_win_dir;\n"; *(const char * *)tb_grow(v_lines) = tb_v3581; }
    { const char * tb_v3582 = "TB_API tb_win_dir *tb_win_opendir(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3582; }
    { const char * tb_v3583 = "    wchar_t *p = tb_wide(path);\n"; *(const char * *)tb_grow(v_lines) = tb_v3583; }
    { const char * tb_v3584 = "    _WDIR *d = p ? _wopendir(p) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3584; }
    { const char * tb_v3585 = "    free(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v3585; }
    { const char * tb_v3586 = "    if (!d) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3586; }
    { const char * tb_v3587 = "    tb_win_dir *r = calloc(1, sizeof *r);\n"; *(const char * *)tb_grow(v_lines) = tb_v3587; }
    { const char * tb_v3588 = "    if (!r) { _wclosedir(d); return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3588; }
    { const char * tb_v3589 = "    r->d = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v3589; }
    { const char * tb_v3590 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v3590; }
    { const char * tb_v3591 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3591; }
    { const char * tb_v3592 = "TB_API struct tb_win_dirent *tb_win_readdir(tb_win_dir *d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3592; }
    { const char * tb_v3593 = "    struct _wdirent *e = _wreaddir(d->d);\n"; *(const char * *)tb_grow(v_lines) = tb_v3593; }
    { const char * tb_v3594 = "    if (!e) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3594; }
    { const char * tb_v3595 = "    if (WideCharToMultiByte(CP_UTF8, 0, e->d_name, -1, d->e.d_name, sizeof d->e.d_name, 0, 0) <= 0) d->e.d_name[0] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3595; }
    { const char * tb_v3596 = "    return &d->e;\n"; *(const char * *)tb_grow(v_lines) = tb_v3596; }
    { const char * tb_v3597 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3597; }
    { const char * tb_v3598 = "TB_API int tb_win_closedir(tb_win_dir *d) { _wclosedir(d->d); free(d); return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3598; }
    { const char * tb_v3599 = "// цвет в консоли — только если удалось включить ESC-последовательности (Windows 10+)\n"; *(const char * *)tb_grow(v_lines) = tb_v3599; }
    { const char * tb_v3600 = "TB_API int tb_win_vt = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3600; }
    { const char * tb_v3601 = "TB_API int tb_win_isatty(int fd) { return tb_win_vt && _isatty(fd); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3601; }
    { const char * tb_v3602 = "// число ядер\n"; *(const char * *)tb_grow(v_lines) = tb_v3602; }
    { const char * tb_v3603 = "#ifndef _SC_NPROCESSORS_ONLN\n"; *(const char * *)tb_grow(v_lines) = tb_v3603; }
    { const char * tb_v3604 = "#define _SC_NPROCESSORS_ONLN 84\n"; *(const char * *)tb_grow(v_lines) = tb_v3604; }
    { const char * tb_v3605 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3605; }
    { const char * tb_v3606 = "TB_API long tb_win_sysconf(int what) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3606; }
    { const char * tb_v3607 = "    (void)what;\n"; *(const char * *)tb_grow(v_lines) = tb_v3607; }
    { const char * tb_v3608 = "    SYSTEM_INFO si;\n"; *(const char * *)tb_grow(v_lines) = tb_v3608; }
    { const char * tb_v3609 = "    GetSystemInfo(&si);\n"; *(const char * *)tb_grow(v_lines) = tb_v3609; }
    { const char * tb_v3610 = "    return (long)si.dwNumberOfProcessors;\n"; *(const char * *)tb_grow(v_lines) = tb_v3610; }
    { const char * tb_v3611 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3611; }
    { const char * tb_v3612 = "#define fopen(p, m) tb_win_fopen(p, m)\n"; *(const char * *)tb_grow(v_lines) = tb_v3612; }
    { const char * tb_v3613 = "#define stat(p, s) tb_win_stat(p, s)\n"; *(const char * *)tb_grow(v_lines) = tb_v3613; }
    { const char * tb_v3614 = "#define mkdir(p, mode) tb_win_mkdir(p)\n"; *(const char * *)tb_grow(v_lines) = tb_v3614; }
    { const char * tb_v3615 = "#define rmdir(p) tb_win_rmdir(p)\n"; *(const char * *)tb_grow(v_lines) = tb_v3615; }
    { const char * tb_v3616 = "#define unlink(p) tb_win_unlink(p)\n"; *(const char * *)tb_grow(v_lines) = tb_v3616; }
    { const char * tb_v3617 = "#define rename(a, b) tb_win_rename(a, b)\n"; *(const char * *)tb_grow(v_lines) = tb_v3617; }
    { const char * tb_v3618 = "#define getenv(n) tb_win_getenv(n)\n"; *(const char * *)tb_grow(v_lines) = tb_v3618; }
    { const char * tb_v3619 = "#undef popen\n"; *(const char * *)tb_grow(v_lines) = tb_v3619; }
    { const char * tb_v3620 = "#undef pclose\n"; *(const char * *)tb_grow(v_lines) = tb_v3620; }
    { const char * tb_v3621 = "#define popen(c, m) tb_win_popen(c, m)\n"; *(const char * *)tb_grow(v_lines) = tb_v3621; }
    { const char * tb_v3622 = "#define pclose(f) _pclose(f)\n"; *(const char * *)tb_grow(v_lines) = tb_v3622; }
    { const char * tb_v3623 = "#define DIR tb_win_dir\n"; *(const char * *)tb_grow(v_lines) = tb_v3623; }
    { const char * tb_v3624 = "#define dirent tb_win_dirent\n"; *(const char * *)tb_grow(v_lines) = tb_v3624; }
    { const char * tb_v3625 = "#define opendir(p) tb_win_opendir(p)\n"; *(const char * *)tb_grow(v_lines) = tb_v3625; }
    { const char * tb_v3626 = "#define readdir(d) tb_win_readdir(d)\n"; *(const char * *)tb_grow(v_lines) = tb_v3626; }
    { const char * tb_v3627 = "#define closedir(d) tb_win_closedir(d)\n"; *(const char * *)tb_grow(v_lines) = tb_v3627; }
    { const char * tb_v3628 = "#define isatty(fd) tb_win_isatty(fd)\n"; *(const char * *)tb_grow(v_lines) = tb_v3628; }
    { const char * tb_v3629 = "#define sysconf(x) tb_win_sysconf(x)\n"; *(const char * *)tb_grow(v_lines) = tb_v3629; }
    { const char * tb_v3630 = "#define localtime_r(t, r) (localtime_s((r), (t)) == 0 ? (r) : 0)\n"; *(const char * *)tb_grow(v_lines) = tb_v3630; }
    { const char * tb_v3631 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3631; }
    { const char * tb_v3632 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3632; }
    { const char * tb_v3633 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3633; }
    { const char * tb_v3634 = "// подсказки для clang / gcc: ошибка бывает редко, а tb_crash не возвращается\n"; *(const char * *)tb_grow(v_lines) = tb_v3634; }
    { const char * tb_v3635 = "#if defined(__GNUC__)\n"; *(const char * *)tb_grow(v_lines) = tb_v3635; }
    { const char * tb_v3636 = "#define TB_RARE(x) __builtin_expect(!!(x), 0)\n"; *(const char * *)tb_grow(v_lines) = tb_v3636; }
    { const char * tb_v3637 = "#define TB_COLD __attribute__((cold, noreturn, noinline))\n"; *(const char * *)tb_grow(v_lines) = tb_v3637; }
    { const char * tb_v3638 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3638; }
    { const char * tb_v3639 = "#define TB_RARE(x) (x)\n"; *(const char * *)tb_grow(v_lines) = tb_v3639; }
    { const char * tb_v3640 = "#define TB_COLD\n"; *(const char * *)tb_grow(v_lines) = tb_v3640; }
    { const char * tb_v3641 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3641; }
    { const char * tb_v3642 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3642; }
    { const char * tb_v3643 = "// список: кусок памяти, len элементов по size байт, место на cap\n"; *(const char * *)tb_grow(v_lines) = tb_v3643; }
    { const char * tb_v3644 = "typedef struct { char *data; long long len; long long cap; long long size; } tb_list;\n"; *(const char * *)tb_grow(v_lines) = tb_v3644; }
    { const char * tb_v3645 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3645; }
    { const char * tb_v3646 = "// ---------- язык сообщений: русский или английский ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3646; }
    { const char * tb_v3647 = "// TB_LANG=en/ru, иначе файл ~/.tachbit/lang (его пишет tb lang en/ru), иначе язык системы (LANG).\n"; *(const char * *)tb_grow(v_lines) = tb_v3647; }
    { const char * tb_v3648 = "// tb_tr заменяет русские куски сообщения английскими по таблице tb_lang_tab.\n"; *(const char * *)tb_grow(v_lines) = tb_v3648; }
    { const char * tb_v3649 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3649; }
    { const char * tb_v3650 = "#define tb_tr(s) (s)\n"; *(const char * *)tb_grow(v_lines) = tb_v3650; }
    { const char * tb_v3651 = "#define tb_lang_en() 0\n"; *(const char * *)tb_grow(v_lines) = tb_v3651; }
    { const char * tb_v3652 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3652; }
    { const char * tb_v3653 = "// ---- TB_LANG_TAB (сделано tools/embed_lang.py, не правь руками) ----\n"; *(const char * *)tb_grow(v_lines) = tb_v3653; }
    { const char * tb_v3654 = "static const char *const tb_lang_tab[] = {\n"; *(const char * *)tb_grow(v_lines) = tb_v3654; }
    { const char * tb_v3655 = "    \"кусок живёт только внутри своего цикла: его можно читать и менять по номеру, ходить по нему each и передавать в функцию, но нельзя сохранять, растить .add и уменьшать .pop\", \"a piece lives only inside its loop: you can read and change it by number, go over it with each and pass it to a function, but you cannot keep it, grow it with .add or shrink it with .pop\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3655; }
    { const char * tb_v3656 = "    \"в background функция получает только int, dec, bool, text и channel (а список — через move: f(move xs)): списки и obj могли бы меняться сразу из двух мест\", \"in background a function gets only int, dec, bool, text and channel (and a list via move: f(move xs)): lists and obj could be changed from two places at once\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3656; }
    { const char * tb_v3657 = "    \"внутри on all cores эта функция меняет полученный список или obj, а он снаружи цикла: собери свой список или obj внутри цикла и передай его\", \"inside on all cores this function changes a list or obj it got, and that one is outside the loop: make your own list or obj inside the loop and pass it\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3657; }
    { const char * tb_v3658 = "    \"для ядра нужен clang (или инструменты LLVM: opt, llc, llvm-link): на Mac — xcode-select --install, на Linux — apt install clang\", \"a kernel needs clang (or LLVM tools: opt, llc, llvm-link): on Mac — xcode-select --install, on Linux — apt install clang\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3658; }
    { const char * tb_v3659 = "    \"пока жив ярлык на элемент этого списка или dict, его нельзя растить и уменьшать: память переедет, и ярлык поведёт в пустоту\", \"while a link to an element of this list or dict is alive, it cannot grow or shrink: the memory would move and the link would point to nothing\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3659; }
    { const char * tb_v3660 = "    \"из dict нельзя убирать ключи, пока по нему идёт each: часть ключей пропустится. Собери ключи в список и убери после цикла\", \"you cannot remove keys from a dict while each goes over it: some keys would be skipped. Collect the keys in a list and remove them after the loop\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3660; }
    { const char * tb_v3661 = "    \"этот список уже отдан в background через move: им больше пользоваться нельзя (можно дать ему новое значение: xs = [1, 2])\", \"this list was already given to background with move: it cannot be used any more (you can give it a new value: xs = [1, 2])\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3661; }
    { const char * tb_v3662 = "    \"через move пока отдают список или dict из int, dec, bool, text или channel: obj внутри могли бы быть видны ещё откуда-то\", \"for now move gives away only a list or dict of int, dec, bool, text or channel: obj inside could be seen from somewhere else\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3662; }
    { const char * tb_v3663 = "    \"draw_round(x, y, ширина, высота, радиус, \\\"углы\\\", цвет)  — углы: \\\"\\\" все, \\\"top\\\", \\\"bottom\\\", \\\"left\\\", \\\"right\\\", \\\"tl tr bl br\\\"\", \"draw_round(x, y, width, height, radius, \\\"corners\\\", color)  — corners: \\\"\\\" all, \\\"top\\\", \\\"bottom\\\", \\\"left\\\", \\\"right\\\", \\\"tl tr bl br\\\"\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3663; }
    { const char * tb_v3664 = "    \"внутри temp не видно списков, dict и obj снаружи (кроме списков чисел): создай данные внутри temp или передай числа\", \"lists, dict and obj from outside are not seen inside temp (except number lists): make the data inside temp or pass numbers\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3664; }
    { const char * tb_v3665 = "    \"у gpu func параметры int, dec, bool, а первым может быть p: pixel (точка), v: corner (угол) или s: screen (экран)\", \"gpu func parameters are int, dec, bool, and the first can be p: pixel, v: corner or s: screen\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3665; }
    { const char * tb_v3666 = "    \"эту shared меняет функция, которая идёт параллельно (background или on all cores): меняй её под замком  lock имя\", \"this shared is changed by a function that runs in parallel (background or on all cores): change it under a lock  lock name\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3666; }
    { const char * tb_v3667 = "    \"эта функция меняет список, а на его элемент смотрит живой ярлык: если список вырастет, ярлык поведёт в пустоту\", \"this function changes a list while a live link looks at its element: if the list grows, the link would point to nothing\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3667; }
    { const char * tb_v3668 = "    \"в цикле через move отдают только список, созданный в этом же шаге цикла: иначе на следующем шаге его уже нет\", \"in a loop move gives away only a list made in this same loop step: otherwise it is gone on the next step\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3668; }
    { const char * tb_v3669 = "    \"в функцию отдают ярлык на элемент списка и сам список: если функция вырастит список, ярлык поведёт в пустоту\", \"the function gets a link to a list element and the list itself: if the function grows the list, the link would point to nothing\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3669; }
    { const char * tb_v3670 = "    \"  tachbit app    файл.tb   сделать программу для Омниума (файл.oapp); --own — своим машинным кодом, без LLVM\", \"  tachbit app    file.tb   make a program for Omnium (file.oapp); --own — own machine code, without LLVM\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3670; }
    { const char * tb_v3671 = "    \"этот список виден ещё откуда-то (второе имя или лежит в другом списке/obj): move отдал бы его сразу двоим\", \"this list is seen from somewhere else (a second name, or it lies in another list/obj): move would give it to two at once\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3671; }
    { const char * tb_v3672 = "    \"в gpu func можно звать только встроенные числовые функции (sin, cos, mix, noise ...) и другие gpu func\", \"in gpu func you can call only built-in number functions (sin, cos, mix, noise ...) and other gpu func\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3672; }
    { const char * tb_v3673 = "    \"из temp наружу можно сохранить только int, dec или bool: текст, списки и obj удалятся в конце блока\", \"only int, dec or bool can be kept outside temp: texts, lists and obj are deleted at the end of the block\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3673; }
    { const char * tb_v3674 = "    \"spot_light(номер 0…7, x, y, z, куда x, куда y, куда z, ширина в градусах, цвет, дальность) — фонарь\", \"spot_light(number 0…7, x, y, z, look x, look y, look z, width in degrees, color, range) — a spotlight\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3674; }
    { const char * tb_v3675 = "    \" нельзя менять списки и obj снаружи цикла и то, что из них взято (свои, созданные внутри, — можно)\", \" you cannot change lists and obj from outside the loop, or what was taken from them (your own, made inside, are fine)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3675; }
    { const char * tb_v3676 = "    \"подключение C-файлов через link будет в версии 0.9 (вместе с danger); файлы Tachbit подключает use\", \"connecting C files with link will come in version 0.9 (together with danger); use connects Tachbit files\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3676; }
    { const char * tb_v3677 = "    \"mouse_lock(true)  —  мышь для игр от первого лица: курсора нет, поворот — mouse_dx() и mouse_dy()\", \"mouse_lock(true)  —  mouse for first-person games: no cursor, turning — mouse_dx() and mouse_dy()\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3677; }
    { const char * tb_v3678 = "    \"у этого значения нет методов: они есть у списков (.add .pop) и dict (.has .remove .keys .values)\", \"this value has no methods: lists have them (.add .pop) and dict (.has .remove .keys .values)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3678; }
    { const char * tb_v3679 = "    \"программа упала: ошибка памяти. Это ошибка Tachbit, а не твоя: пришли, пожалуйста, эту программу\", \"the program crashed: memory error. This is a Tachbit bug, not yours: please send this program\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3679; }
    { const char * tb_v3680 = "    \"skip и stop внутри lock работают только для циклов внутри lock: иначе замок останется закрытым\", \"skip and stop inside lock work only for loops inside lock: otherwise the lock would stay closed\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3680; }
    { const char * tb_v3681 = "    \"не получилось собрать библиотеку. Это ошибка Tachbit, а не твоя: твой код прошёл все проверки.\", \"could not build the library. This is a Tachbit bug, not yours: your code passed all checks.\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3681; }
    { const char * tb_v3682 = "    \"unlock пишется прямо в блоке lock, не внутри if и циклов: так всегда ясно, взят замок или нет\", \"unlock is written right in the lock block, not inside if or loops: that way it is always clear whether the lock is taken\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3682; }
    { const char * tb_v3683 = "    \"не получилось собрать программу. Это ошибка Tachbit, а не твоя: твой код прошёл все проверки.\", \"could not build the program. This is a Tachbit bug, not yours: your code passed all checks.\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3683; }
    { const char * tb_v3684 = "    \", а где-то наоборот — две работы могут ждать друг друга вечно. Бери их везде в одном порядке\", \", and somewhere the other way — two jobs can wait for each other forever. Take them in the same order everywhere\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3684; }
    { const char * tb_v3685 = "    \"  --llvm / --c   к build / run: собрать через LLVM (так и есть, если есть clang) или через C\", \"  --llvm / --c   for build / run: build through LLVM (the default if there is clang) or through C\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3685; }
    { const char * tb_v3686 = "    \"через move отдают только свою переменную, созданную в этой функции (не параметр и не ярлык)\", \"move gives away only your own variable made in this function (not a parameter and not a link)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3686; }
    { const char * tb_v3687 = "    \"внутри lock return нельзя: замок останется закрытым; сохрани число снаружи и выйди из блока\", \"return is not allowed inside lock: the lock would stay closed; save the number outside and leave the block\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3687; }
    { const char * tb_v3688 = "    \"ярлык на элемент list bool нельзя: там каждый элемент — один бит, у бита нет своего адреса\", \"a link to an element of list bool is not allowed: each element there is one bit, and a bit has no address of its own\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3688; }
    { const char * tb_v3689 = "    \"функция вызывает сама себя раньше первого return со значением: поставь простой return выше\", \"the function calls itself before its first return with a value: put a simple return above\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3689; }
    { const char * tb_v3690 = "    \"внутри each ... by N return нельзя: сохрани число в переменную снаружи и выйди через stop\", \"return is not allowed inside each ... by N: save the number in an outside variable and leave with stop\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3690; }
    { const char * tb_v3691 = "    \"mouse_wheel()  →  на сколько шагов повернули колёсико: + вперёд, − назад, 0 — не крутили\", \"mouse_wheel()  →  how many steps the wheel turned: + forward, − back, 0 — not turned\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3691; }
    { const char * tb_v3692 = "    \"shadows(размер) — тени от солнца в квадрате размер × размер вокруг камеры; 0 — без теней\", \"shadows(size) — sun shadows in a size × size square around the camera; 0 — no shadows\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3692; }
    { const char * tb_v3693 = "    \"light_shadow(лампа 0…7, true) — лампа даёт тени на сетки со своими шейдерами (до 4 ламп)\", \"light_shadow(lamp 0…7, true) — the lamp casts shadows on meshes with their own shaders (up to 4 lamps)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3693; }
    { const char * tb_v3694 = "    \"функция for c не может заканчиваться ошибкой: C не умеет её поймать; верни, например, -1\", \"a for c function cannot end with an error: C cannot catch it; return, for example, -1\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3694; }
    { const char * tb_v3695 = "    \"mesh_bounds(сетка, x, y, z, радиус) — шар, из которого сетка не выходит (для отсечения)\", \"mesh_bounds(mesh, x, y, z, radius) — a ball the mesh never leaves (for culling)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3695; }
    { const char * tb_v3696 = "    \"mesh_free(сетка) — сетка больше не нужна: память отдаётся, номер достанется новой сетке\", \"mesh_free(mesh) — the mesh is not needed any more: memory is freed, the number goes to a new mesh\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3696; }
    { const char * tb_v3697 = "    \"функция может закончиться ошибкой: напиши  try f(),  f() or запасное  или  f() else err\", \"the function can end with an error: write  try f(),  f() or fallback  or  f() else err\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3697; }
    { const char * tb_v3698 = "    \"shared внутри on all cores можно только менять через += или -=, а читать — после цикла\", \"shared inside on all cores can only be changed with += or -=, and read after the loop\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3698; }
    { const char * tb_v3699 = "    \"функция с fail в background пока нельзя: пусть она отдаёт текст ошибки обычным выходом\", \"a function with fail cannot go to background yet: let it give the error text as a normal output\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3699; }
    { const char * tb_v3700 = "    \"у поля shape пишется размер: u8, u16, u32, u64, i8, i16, i32, i64, bits N или bytes N\", \"a shape field has a size: u8, u16, u32, u64, i8, i16, i32, i64, bits N or bytes N\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3700; }
    { const char * tb_v3701 = "    \"число не помещается в int: больше 9223372036854775807 или меньше -9223372036854775808\", \"the number does not fit in int: more than 9223372036854775807 or less than -9223372036854775808\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3701; }
    { const char * tb_v3702 = "    \"ярлык на элемент списка колонок нельзя: возьми ярлык на качество, например pts[i].x\", \"a link to an element of a column list is not allowed: take a link to a field, for example pts[i].x\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3702; }
    { const char * tb_v3703 = "    \"это может закончиться ошибкой: напиши  try ...,  ... or запасное  или  ... else err\", \"this can end with an error: write  try ...,  ... or fallback  or  ... else err\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3703; }
    { const char * tb_v3704 = "    \"список нельзя растить, пока по нему идёт each ... by N (и сам кусок растить нельзя)\", \"a list cannot grow while each ... by N goes over it (and the piece itself cannot grow)\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3704; }
    { const char * tb_v3705 = "    \"shader_image(сетка, слот 0…3, картинка) — картинка для tex_r(слот, u, v) в шейдере\", \"shader_image(mesh, slot 0…3, picture) — a picture for tex_r(slot, u, v) in the shader\",\n"; *(const char * *)tb_grow(v_lines) = tb_v3705; }
