    { const char * tb_v4578 = "// ---------- падение по памяти: понятное сообщение вместо «Segmentation fault» ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4578; }
    { const char * tb_v4579 = "// Чаще всего это стек: функция зовёт себя слишком глубоко. Обработчик работает\n"; *(const char * *)tb_grow(v_lines) = tb_v4579; }
    { const char * tb_v4580 = "// на своём маленьком стеке (sigaltstack), потому что основной уже кончился.\n"; *(const char * *)tb_grow(v_lines) = tb_v4580; }
    { const char * tb_v4581 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v4581; }
    { const char * tb_v4582 = "#include <signal.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v4582; }
    { const char * tb_v4583 = "#include <sys/resource.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v4583; }
    { const char * tb_v4584 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v4584; }
    { const char * tb_v4585 = "// На Windows нет сигналов и sigaltstack: переполнение стека ловит обработчик\n"; *(const char * *)tb_grow(v_lines) = tb_v4585; }
    { const char * tb_v4586 = "// исключений (tb_guard_init ниже), а место для него в конце стека даёт\n"; *(const char * *)tb_grow(v_lines) = tb_v4586; }
    { const char * tb_v4587 = "// SetThreadStackGuarantee. Этот sigaltstack только помнит память потока,\n"; *(const char * *)tb_grow(v_lines) = tb_v4587; }
    { const char * tb_v4588 = "// чтобы tb_tramp_run мог её отдать, и просит у Windows запас стека.\n"; *(const char * *)tb_grow(v_lines) = tb_v4588; }
    { const char * tb_v4589 = "typedef struct { void *ss_sp; size_t ss_size; int ss_flags; } stack_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v4589; }
    { const char * tb_v4590 = "#define SS_DISABLE 4\n"; *(const char * *)tb_grow(v_lines) = tb_v4590; }
    { const char * tb_v4591 = "TB_API _Thread_local void *tb_win_alt;\n"; *(const char * *)tb_grow(v_lines) = tb_v4591; }
    { const char * tb_v4592 = "TB_API int sigaltstack(const stack_t *ss, stack_t *old) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4592; }
    { const char * tb_v4593 = "    if (old) { old->ss_sp = tb_win_alt; old->ss_size = 0; old->ss_flags = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4593; }
    { const char * tb_v4594 = "    if (ss) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4594; }
    { const char * tb_v4595 = "        tb_win_alt = (ss->ss_flags & SS_DISABLE) ? 0 : ss->ss_sp;\n"; *(const char * *)tb_grow(v_lines) = tb_v4595; }
    { const char * tb_v4596 = "        if (!(ss->ss_flags & SS_DISABLE)) { ULONG g = 65536; SetThreadStackGuarantee(&g); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4596; }
    { const char * tb_v4597 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4597; }
    { const char * tb_v4598 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4598; }
    { const char * tb_v4599 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4599; }
    { const char * tb_v4600 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4600; }
    { const char * tb_v4601 = "// у каждого потока своё: где начинается его стек и сколько в нём места\n"; *(const char * *)tb_grow(v_lines) = tb_v4601; }
    { const char * tb_v4602 = "TB_API _Thread_local char *tb_main_sp;\n"; *(const char * *)tb_grow(v_lines) = tb_v4602; }
    { const char * tb_v4603 = "TB_API _Thread_local long long tb_stack_lim;\n"; *(const char * *)tb_grow(v_lines) = tb_v4603; }
    { const char * tb_v4604 = "#define TB_THREAD_STACK (8LL << 20)\n"; *(const char * *)tb_grow(v_lines) = tb_v4604; }
    { const char * tb_v4605 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v4605; }
    { const char * tb_v4606 = "TB_API void tb_on_segv(int sig, siginfo_t *si, void *u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4606; }
    { const char * tb_v4607 = "    (void)sig; (void)u;\n"; *(const char * *)tb_grow(v_lines) = tb_v4607; }
