    { const char * tb_v4611 = "        lim = 8LL << 20;\n"; *(const char * *)tb_grow(v_lines) = tb_v4611; }
    { const char * tb_v4612 = "        struct rlimit rl;\n"; *(const char * *)tb_grow(v_lines) = tb_v4612; }
    { const char * tb_v4613 = "        if (getrlimit(RLIMIT_STACK, &rl) == 0 && rl.rlim_cur != RLIM_INFINITY) lim = (long long)rl.rlim_cur;\n"; *(const char * *)tb_grow(v_lines) = tb_v4613; }
    { const char * tb_v4614 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4614; }
