    { const char * tb_v4620 = "        m = tb_lang_en_v == 1 ? \"the program crashed: memory error. This is a Tachbit bug, not yours: please send this program\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v4620; }
    { const char * tb_v4621 = "                              : \"программа упала: ошибка памяти. Это ошибка Tachbit, а не твоя: пришли, пожалуйста, эту программу\\n\";\n"; *(const char * *)tb_grow(v_lines) = tb_v4621; }
    { const char * tb_v4622 = "    if (write(2, m, strlen(m)) < 0) _exit(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4622; }
