    { const char * tb_v4921 = "// munmap здесь зовётся только для целого куска из tb_gsys — это VirtualFree(MEM_RELEASE).\n"; *(const char * *)tb_grow(v_lines) = tb_v4921; }
    { const char * tb_v4922 = "TB_API char *tb_gsys(long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4922; }
    { const char * tb_v4923 = "    char *m = VirtualAlloc(0, (SIZE_T)size, MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE);\n"; *(const char * *)tb_grow(v_lines) = tb_v4923; }
