    { const char * tb_v4991 = "TB_API void tb_gc_collect(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v4991; }
    { const char * tb_v4992 = "TB_API void *tb_galloc_locked(long long n, int np) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4992; }
    { const char * tb_v4993 = "    if (!tb_gready) tb_gsetup();\n"; *(const char * *)tb_grow(v_lines) = tb_v4993; }
