    { const char * tb_v5398 = "    if (TB_RARE(l->len >= l->cap)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5398; }
    { const char * tb_v5399 = "        if (l->cap < 0) tb_crash(0, \"список нельзя растить, пока по нему идёт each ... by N (и сам кусок растить нельзя)\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5399; }
    { const char * tb_v5400 = "        long long old = l->cap / 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v5400; }
    { const char * tb_v5401 = "        l->cap = l->cap * 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v5401; }
