    { const char * tb_v5403 = "        memset(l->data + old, 0, l->cap / 8 - old);\n"; *(const char * *)tb_grow(v_lines) = tb_v5403; }
    { const char * tb_v5404 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5404; }
    { const char * tb_v5405 = "    long long i = l->len++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5405; }
    { const char * tb_v5406 = "    unsigned long long *w = (unsigned long long *)l->data + (i >> 6), m = 1ULL << (i & 63);\n"; *(const char * *)tb_grow(v_lines) = tb_v5406; }
    { const char * tb_v5407 = "    *w = v ? (*w | m) : (*w & ~m);\n"; *(const char * *)tb_grow(v_lines) = tb_v5407; }
