    { const char * tb_v5414 = "// N одинаковых битов в конец (repeat N times: flags.add(true))\n"; *(const char * *)tb_grow(v_lines) = tb_v5414; }
    { const char * tb_v5415 = "TB_API void tb_bfill(tb_list *l, long long n, _Bool v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5415; }
    { const char * tb_v5416 = "    if (n <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5416; }
    { const char * tb_v5417 = "    if (l->cap < 0) tb_crash(0, \"список нельзя растить, пока по нему идёт each ... by N (и сам кусок растить нельзя)\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5417; }
    { const char * tb_v5418 = "    long long need = l->len + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v5418; }
    { const char * tb_v5419 = "    if (need > l->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5419; }
    { const char * tb_v5420 = "        long long old = l->cap / 8, cap = l->cap;\n"; *(const char * *)tb_grow(v_lines) = tb_v5420; }
    { const char * tb_v5421 = "        while (cap < need) cap *= 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v5421; }
    { const char * tb_v5422 = "        l->data = tb_resize(l->data, old, cap / 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v5422; }
