    { const char * tb_v5424 = "        l->cap = cap;\n"; *(const char * *)tb_grow(v_lines) = tb_v5424; }
    { const char * tb_v5425 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5425; }
    { const char * tb_v5426 = "    unsigned long long *w = (unsigned long long *)l->data;\n"; *(const char * *)tb_grow(v_lines) = tb_v5426; }
    { const char * tb_v5427 = "    long long i = l->len;\n"; *(const char * *)tb_grow(v_lines) = tb_v5427; }
    { const char * tb_v5428 = "    for (; i < need && (i & 63); i++) w[i >> 6] = v ? (w[i >> 6] | 1ULL << (i & 63)) : (w[i >> 6] & ~(1ULL << (i & 63)));\n"; *(const char * *)tb_grow(v_lines) = tb_v5428; }
    { const char * tb_v5429 = "    if (need - i >= 64) { memset(w + (i >> 6), v ? 0xff : 0, ((need - i) >> 6) * 8); i += (need - i) & ~63LL; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5429; }
    { const char * tb_v5430 = "    for (; i < need; i++) w[i >> 6] = v ? (w[i >> 6] | 1ULL << (i & 63)) : (w[i >> 6] & ~(1ULL << (i & 63)));\n"; *(const char * *)tb_grow(v_lines) = tb_v5430; }
    { const char * tb_v5431 = "    l->len = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v5431; }
    { const char * tb_v5432 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5432; }
    { const char * tb_v5433 = "// значения dict bool лежат байтами — в list bool их надо переложить в биты\n"; *(const char * *)tb_grow(v_lines) = tb_v5433; }
    { const char * tb_v5434 = "TB_API tb_list *tb_bits_of_bytes(tb_list *b) { return tb_bits_from(b->len, (const unsigned char *)b->data); }\n"; *(const char * *)tb_grow(v_lines) = tb_v5434; }
    { const char * tb_v5435 = "// N одинаковых элементов в конец (repeat N times: nums.add(0))\n"; *(const char * *)tb_grow(v_lines) = tb_v5435; }
    { const char * tb_v5436 = "TB_API void tb_fill(tb_list *l, long long n, const void *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5436; }
    { const char * tb_v5437 = "    if (n <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5437; }
    { const char * tb_v5438 = "    if (l->len + n > l->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5438; }
    { const char * tb_v5439 = "        if (l->cap < 0) tb_crash(0, \"список нельзя растить, пока по нему идёт each ... by N (и сам кусок растить нельзя)\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5439; }
    { const char * tb_v5440 = "        long long cap = l->cap * 2 + 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v5440; }
