    { const char * tb_v5443 = "        l->cap = cap;\n"; *(const char * *)tb_grow(v_lines) = tb_v5443; }
    { const char * tb_v5444 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5444; }
    { const char * tb_v5445 = "    char *p = l->data + l->len * l->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v5445; }
    { const char * tb_v5446 = "    int zero = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5446; }
    { const char * tb_v5447 = "    for (long long b = 0; b < l->size; b++) if (((const char *)v)[b]) zero = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5447; }
