    { const char * tb_v5494 = "// ---------- буквы: len, s[i], cut, find, code, char и each считают буквы, а не байты ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v5494; }
    { const char * tb_v5495 = "// Текст хранится в UTF-8: латинская буква — 1 байт, русская — 2, иероглиф — 3, смайлик — 4.\n"; *(const char * *)tb_grow(v_lines) = tb_v5495; }
    { const char * tb_v5496 = "// Байт, который не складывается в букву (испорченный UTF-8, байты с диска), — сам себе буква.\n"; *(const char * *)tb_grow(v_lines) = tb_v5496; }
    { const char * tb_v5497 = "TB_INL long long tb_u8n(const unsigned char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5497; }
    { const char * tb_v5498 = "    unsigned char b = p[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v5498; }
