    { const char * tb_v5500 = "    long long need = b < 0xE0 ? 2 : b < 0xF0 ? 3 : 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v5500; }
    { const char * tb_v5501 = "    for (long long k = 1; k < need; k++) if ((p[k] & 0xC0) != 0x80) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5501; }
    { const char * tb_v5502 = "    return need;\n"; *(const char * *)tb_grow(v_lines) = tb_v5502; }
