    { const char * tb_v5599 = "// *rl — длина s в своей памяти (-1: своей памяти нет, s могли сохранить где-то ещё — сначала копия),\n"; *(const char * *)tb_grow(v_lines) = tb_v5599; }
    { const char * tb_v5600 = "// *rc — сколько там места.\n"; *(const char * *)tb_grow(v_lines) = tb_v5600; }
    { const char * tb_v5601 = "TB_API void tb_app_n(const char **p, long long *rl, long long *rc, const char *b, long long lb);\n"; *(const char * *)tb_grow(v_lines) = tb_v5601; }
    { const char * tb_v5602 = "// число цифрами в конец буфера d[24]: вернёт начало цифр, длину — в *n\n"; *(const char * *)tb_grow(v_lines) = tb_v5602; }
    { const char * tb_v5603 = "TB_INL const char *tb_digits(long long x, char *d, long long *n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5603; }
    { const char * tb_v5604 = "    unsigned long long u = x < 0 ? 0ULL - (unsigned long long)x : (unsigned long long)x;\n"; *(const char * *)tb_grow(v_lines) = tb_v5604; }
    { const char * tb_v5605 = "    char *p = d + 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v5605; }
    { const char * tb_v5606 = "    do { *--p = (char)('0' + u % 10); u /= 10; } while (u);\n"; *(const char * *)tb_grow(v_lines) = tb_v5606; }
