    { const char * tb_v5608 = "    *n = d + 24 - p;\n"; *(const char * *)tb_grow(v_lines) = tb_v5608; }
    { const char * tb_v5609 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v5609; }
