    { const char * tb_v5639 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5639; }
    { const char * tb_v5640 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5640; }
    { const char * tb_v5641 = "    long long need = *rl + lb + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5641; }
