    { const char * tb_v5669 = "    if (b < 1 || b > 255) tb_crash(line, \"byte_char: байт должен быть от 1 до 255 (байт 0 кончает текст)\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5669; }
