    { const char * tb_v5697 = "TB_API long long tb_div(long long a, long long b, int line) { if (b == 0) tb_crash(line, \"деление на ноль\"); if (b == -1) return tb_nego(a, line); return a / b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5697; }
