    { const char * tb_v5969 = "    if (p == 0) { tb_err = \"не могу запустить curl\"; return \"\"; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5969; }
    { const char * tb_v5970 = "    size_t cap = 4096, len = 0, got;\n"; *(const char * *)tb_grow(v_lines) = tb_v5970; }
    { const char * tb_v5971 = "    char *buf = tb_tmem(cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v5971; }
