    { const char * tb_v6014 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v6014; }
    { const char * tb_v6015 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6015; }
    { const char * tb_v6016 = "// строка JSON (p смотрит на \") → обычный текст\n"; *(const char * *)tb_grow(v_lines) = tb_v6016; }
    { const char * tb_v6017 = "TB_API const char *tb_js_str(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6017; }
    { const char * tb_v6018 = "    const char *e = tb_js_skip(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v6018; }
    { const char * tb_v6019 = "    if (!e) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6019; }
