    { const char * tb_v6318 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v6318; }
    { const char * tb_v6319 = "// ---------- dict: ключи и значения лежат в двух списках по порядку добавления,\n"; *(const char * *)tb_grow(v_lines) = tb_v6319; }
    { const char * tb_v6320 = "// а найти номер по ключу можно тремя способами (mode):\n"; *(const char * *)tb_grow(v_lines) = tb_v6320; }
    { const char * tb_v6321 = "//   1 — «номер = адрес»: ключи int шли подряд base, base+1, base+2 ... — номер = ключ - base, без поиска;\n"; *(const char * *)tb_grow(v_lines) = tb_v6321; }
    { const char * tb_v6322 = "//   2 — «адресное хранение»: ключи int лежат плотно — pos[ключ - base] = номер + 1, один взгляд;\n"; *(const char * *)tb_grow(v_lines) = tb_v6322; }
    { const char * tb_v6323 = "//   0 — таблица slots с хешем (текст или разбросанные числа) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6323; }
    { const char * tb_v6324 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v6324; }
