    { const char * tb_v6326 = "    int mode; long long base; long long *pos; long long npos;\n"; *(const char * *)tb_grow(v_lines) = tb_v6326; }
    { const char * tb_v6327 = "} tb_dict;\n"; *(const char * *)tb_grow(v_lines) = tb_v6327; }
    { const char * tb_v6328 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v6328; }
    { const char * tb_v6329 = "// список целиком: сам список, его память и (texts) тексты-элементы\n"; *(const char * *)tb_grow(v_lines) = tb_v6329; }
    { const char * tb_v6330 = "TB_API void tb_export_list(tb_list *l, int texts) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6330; }
    { const char * tb_v6331 = "    if (!l) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6331; }
    { const char * tb_v6332 = "    if (texts) for (long long i = 0; i < l->len; i++) tb_export(((char **)l->data)[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v6332; }
