    { const char * tb_v6343 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6343; }
    { const char * tb_v6344 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6344; }
    { const char * tb_v6345 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v6345; }
    { const char * tb_v6346 = "// ячейка таблицы: номер ключа + 1 (младшие 40 бит) и метка из старших битов хеша\n"; *(const char * *)tb_grow(v_lines) = tb_v6346; }
