    { const char * tb_v6385 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6385; }
    { const char * tb_v6386 = "// память для таблиц dict — там же, где лежат его ключи (временная или обычная)\n"; *(const char * *)tb_grow(v_lines) = tb_v6386; }
