    { const char * tb_v6467 = "        if (k == d->base + n - 1) return;  // подряд — остаёмся в mode 1\n"; *(const char * *)tb_grow(v_lines) = tb_v6467; }
    { const char * tb_v6468 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6468; }
    { const char * tb_v6469 = "    if (d->mode == 1 || d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6469; }
    { const char * tb_v6470 = "        // плотно ли: ключи не дальше 4 ячеек на один ключ\n"; *(const char * *)tb_grow(v_lines) = tb_v6470; }
