    { const char * tb_v6481 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6481; }
    { const char * tb_v6482 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6482; }
    { const char * tb_v6483 = "// место под значение ключа k; если ключа нет — добавить со значением *def\n"; *(const char * *)tb_grow(v_lines) = tb_v6483; }
    { const char * tb_v6484 = "TB_API void *tb_dput(tb_dict *d, const void *k, const void *def) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6484; }
    { const char * tb_v6485 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v6485; }
    { const char * tb_v6486 = "    if (at >= 0) return d->vals->data + at * d->vals->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v6486; }
    { const char * tb_v6487 = "    memcpy(tb_grow(d->keys), k, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6487; }
    { const char * tb_v6488 = "    void *v = tb_grow(d->vals);\n"; *(const char * *)tb_grow(v_lines) = tb_v6488; }
    { const char * tb_v6489 = "    if (def) memcpy(v, def, d->vals->size); else memset(v, 0, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6489; }
    { const char * tb_v6490 = "    if (d->mode != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6490; }
    { const char * tb_v6491 = "        // без поиска; если ключ лёг далеко, tb_dplace_int сам перейдёт на хеш и впишет все ключи\n"; *(const char * *)tb_grow(v_lines) = tb_v6491; }
    { const char * tb_v6492 = "        tb_dplace_int(d, *(const long long *)k);\n"; *(const char * *)tb_grow(v_lines) = tb_v6492; }
    { const char * tb_v6493 = "        return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v6493; }
    { const char * tb_v6494 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6494; }
    { const char * tb_v6495 = "    if (d->keys->len * 2 > d->nslots) tb_dreindex(d, d->nslots * 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v6495; }
    { const char * tb_v6496 = "    else {\n"; *(const char * *)tb_grow(v_lines) = tb_v6496; }
    { const char * tb_v6497 = "        unsigned long long h = tb_hash(d, k), mask = d->nslots - 1, i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v6497; }
    { const char * tb_v6498 = "        while (d->slots[i] != 0) i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v6498; }
    { const char * tb_v6499 = "        d->slots[i] = d->keys->len | TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v6499; }
    { const char * tb_v6500 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6500; }
    { const char * tb_v6501 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v6501; }
    { const char * tb_v6502 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6502; }
    { const char * tb_v6503 = "TB_API void *tb_dget(tb_dict *d, const void *k, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6503; }
    { const char * tb_v6504 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v6504; }
    { const char * tb_v6505 = "    if (TB_RARE(at < 0)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6505; }
    { const char * tb_v6506 = "        if (d->text) tb_crash(line, tb_cat(\"в dict нет ключа: \", *(const char * const *)k));\n"; *(const char * *)tb_grow(v_lines) = tb_v6506; }
    { const char * tb_v6507 = "        tb_crash(line, tb_cat(\"в dict нет ключа: \", tb_itos(*(const long long *)k)));\n"; *(const char * *)tb_grow(v_lines) = tb_v6507; }
    { const char * tb_v6508 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6508; }
