    { const char * tb_v6511 = "// together: шаг 1 — просим память принести место ключа заранее\n"; *(const char * *)tb_grow(v_lines) = tb_v6511; }
    { const char * tb_v6512 = "TB_INL unsigned long long tb_dpre1(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6512; }
    { const char * tb_v6513 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6513; }
