    { const char * tb_v6526 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6526; }
    { const char * tb_v6527 = "// шаг 2 — место приехало: просим принести ключ и значение\n"; *(const char * *)tb_grow(v_lines) = tb_v6527; }
    { const char * tb_v6528 = "TB_INL void tb_dpre2(tb_dict *d, unsigned long long i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6528; }
    { const char * tb_v6529 = "    if (i == ~0ULL || d->mode == 1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6529; }
