    { const char * tb_v6559 = "TB_API void *tb_obj_mem_np(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6559; }
    { const char * tb_v6560 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6560; }
    { const char * tb_v6561 = "    return tb_gc_alloc_np(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6561; }
    { const char * tb_v6562 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6562; }
    { const char * tb_v6563 = "// ---------- background: работа в своём потоке ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6563; }
    { const char * tb_v6564 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v6564; }
    { const char * tb_v6565 = "typedef struct { pthread_t th; int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v6565; }
    { const char * tb_v6566 = "TB_API void tb_task_start(tb_task *t, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6566; }
    { const char * tb_v6567 = "    t->done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6567; }
    { const char * tb_v6568 = "    if (tb_thread_create(&t->th, run, arg) != 0) tb_crash(0, \"не получилось запустить background\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6568; }
    { const char * tb_v6569 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6569; }
    { const char * tb_v6570 = "// a = service f(): в программе с ОС служба — тот же background (запас памяти есть только в ядре)\n"; *(const char * *)tb_grow(v_lines) = tb_v6570; }
    { const char * tb_v6571 = "TB_API void tb_service_start(tb_task *t, void *(*run)(void *), void *arg) { tb_task_start(t, run, arg); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6571; }
    { const char * tb_v6572 = "// a.wait: дождаться потока (один раз) и отдать адрес ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v6572; }
    { const char * tb_v6573 = "TB_API void *tb_wait(tb_task *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6573; }
    { const char * tb_v6574 = "    if (!t->done) { pthread_join(t->th, 0); t->done = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6574; }
    { const char * tb_v6575 = "    return t->res;\n"; *(const char * *)tb_grow(v_lines) = tb_v6575; }
    { const char * tb_v6576 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6576; }
    { const char * tb_v6577 = "// a.crashed: в обычной программе падение задачи роняет всю программу — сюда доходят только целые\n"; *(const char * *)tb_grow(v_lines) = tb_v6577; }
    { const char * tb_v6578 = "TB_API _Bool tb_crashed(tb_task *t) { tb_wait(t); return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6578; }
    { const char * tb_v6579 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6579; }
    { const char * tb_v6580 = "TB_API int tb_dhas(tb_dict *d, const void *k) { return tb_dfind(d, k) >= 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6580; }
    { const char * tb_v6581 = "TB_API void tb_dremove(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6581; }
    { const char * tb_v6582 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v6582; }
    { const char * tb_v6583 = "    if (at < 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6583; }
    { const char * tb_v6584 = "    if (d->mode != 0) tb_dto_hash(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v6584; }
    { const char * tb_v6585 = "    long long last = d->keys->len - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6585; }
    { const char * tb_v6586 = "    // на место удалённого ставим последний: порядок меняется только у него\n"; *(const char * *)tb_grow(v_lines) = tb_v6586; }
    { const char * tb_v6587 = "    memcpy(d->keys->data + at * d->keys->size, d->keys->data + last * d->keys->size, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6587; }
    { const char * tb_v6588 = "    memcpy(d->vals->data + at * d->vals->size, d->vals->data + last * d->vals->size, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6588; }
    { const char * tb_v6589 = "    d->keys->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6589; }
