    { const char * tb_v6592 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6592; }
    { const char * tb_v6593 = "TB_API tb_dict *tb_dict_from(int text, long long vsize, long long n, const void *keys, const void *vals) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6593; }
    { const char * tb_v6594 = "    tb_dict *d = tb_dict_new(text, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v6594; }
    { const char * tb_v6595 = "    long long ksize = d->keys->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v6595; }
    { const char * tb_v6596 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6596; }
    { const char * tb_v6597 = "        memcpy(tb_dput(d, (const char *)keys + i * ksize, 0), (const char *)vals + i * vsize, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v6597; }
