    { const char * tb_v6631 = "TB_API void *(*tb_pool_work)(void *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6631; }
    { const char * tb_v6632 = "TB_API void *tb_pool_job = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6632; }
    { const char * tb_v6633 = "TB_API void *tb_pool_loop(void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6633; }
    { const char * tb_v6634 = "    int me = (int)(long long)arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v6634; }
    { const char * tb_v6635 = "    // поток пула не считается «работающим», пока ждёт: уборка памяти может идти\n"; *(const char * *)tb_grow(v_lines) = tb_v6635; }
    { const char * tb_v6636 = "    __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v6636; }
    { const char * tb_v6637 = "    long long seen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6637; }
    { const char * tb_v6638 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6638; }
    { const char * tb_v6639 = "        // немного ждём без сна: циклы на ядрах часто идут один за другим\n"; *(const char * *)tb_grow(v_lines) = tb_v6639; }
    { const char * tb_v6640 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_gen, __ATOMIC_ACQUIRE) == seen; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6640; }
    { const char * tb_v6641 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v6641; }
    { const char * tb_v6642 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6642; }
    { const char * tb_v6643 = "        while (tb_pool_gen == seen) pthread_cond_wait(&tb_pool_go, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6643; }
    { const char * tb_v6644 = "        seen = tb_pool_gen;\n"; *(const char * *)tb_grow(v_lines) = tb_v6644; }
    { const char * tb_v6645 = "        int mine = me < tb_pool_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v6645; }
    { const char * tb_v6646 = "        void *(*work)(void *) = tb_pool_work;\n"; *(const char * *)tb_grow(v_lines) = tb_v6646; }
    { const char * tb_v6647 = "        void *job = tb_pool_job;\n"; *(const char * *)tb_grow(v_lines) = tb_v6647; }
    { const char * tb_v6648 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6648; }
    { const char * tb_v6649 = "        if (!mine) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v6649; }
    { const char * tb_v6650 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v6650; }
    { const char * tb_v6651 = "        __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v6651; }
    { const char * tb_v6652 = "        if (__atomic_sub_fetch(&tb_pool_left, 1, __ATOMIC_ACQ_REL) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6652; }
    { const char * tb_v6653 = "            pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6653; }
    { const char * tb_v6654 = "            pthread_cond_signal(&tb_pool_end);\n"; *(const char * *)tb_grow(v_lines) = tb_v6654; }
    { const char * tb_v6655 = "            pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6655; }
    { const char * tb_v6656 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6656; }
    { const char * tb_v6657 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6657; }
    { const char * tb_v6658 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6658; }
    { const char * tb_v6659 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6659; }
    { const char * tb_v6660 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6660; }
    { const char * tb_v6661 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v6661; }
