    { const char * tb_v6666 = "    if (__atomic_exchange_n(&tb_pool_busy, 1, __ATOMIC_ACQ_REL)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6666; }
    { const char * tb_v6667 = "        pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v6667; }
