    { const char * tb_v6673 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6673; }
    { const char * tb_v6674 = "    while (tb_pool_n < n - 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6674; }
    { const char * tb_v6675 = "        pthread_t th;\n"; *(const char * *)tb_grow(v_lines) = tb_v6675; }
    { const char * tb_v6676 = "        if (tb_thread_create(&th, tb_pool_loop, (void *)(long long)tb_pool_n) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6676; }
    { const char * tb_v6677 = "        pthread_detach(th);\n"; *(const char * *)tb_grow(v_lines) = tb_v6677; }
    { const char * tb_v6678 = "        tb_pool_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6678; }
    { const char * tb_v6679 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6679; }
    { const char * tb_v6680 = "    pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6680; }
    { const char * tb_v6681 = "    tb_pool_work = work; tb_pool_job = job; tb_pool_want = n - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6681; }
    { const char * tb_v6682 = "    __atomic_store_n(&tb_pool_left, n - 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v6682; }
