    { const char * tb_v6713 = "static inline void tb_atomic_addi(volatile long long *p, long long v) { uint64_t f = tb_irq_save(); *p += v; tb_irq_restore(f); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6713; }
    { const char * tb_v6714 = "static inline void tb_atomic_addd(volatile double *p, double v) { uint64_t f = tb_irq_save(); *p += v; tb_irq_restore(f); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6714; }
    { const char * tb_v6715 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v6715; }
    { const char * tb_v6716 = "static inline void tb_atomic_addi(volatile long long *p, long long v) { __atomic_fetch_add(p, v, __ATOMIC_SEQ_CST); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6716; }
    { const char * tb_v6717 = "// дробь: сравнить и заменить, пока никто не успел поменять\n"; *(const char * *)tb_grow(v_lines) = tb_v6717; }
    { const char * tb_v6718 = "static inline void tb_atomic_addd(volatile double *p, double v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6718; }
    { const char * tb_v6719 = "    volatile uint64_t *q = (volatile uint64_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v6719; }
    { const char * tb_v6720 = "    uint64_t old = __atomic_load_n(q, __ATOMIC_SEQ_CST), nw;\n"; *(const char * *)tb_grow(v_lines) = tb_v6720; }
    { const char * tb_v6721 = "    do {\n"; *(const char * *)tb_grow(v_lines) = tb_v6721; }
    { const char * tb_v6722 = "        union { uint64_t u; double d; } a, b;\n"; *(const char * *)tb_grow(v_lines) = tb_v6722; }
    { const char * tb_v6723 = "        a.u = old; b.d = a.d + v; nw = b.u;\n"; *(const char * *)tb_grow(v_lines) = tb_v6723; }
    { const char * tb_v6724 = "    } while (!__atomic_compare_exchange_n(q, &old, nw, 0, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST));\n"; *(const char * *)tb_grow(v_lines) = tb_v6724; }
