    { const char * tb_v6738 = "TB_API int tb_mem_check = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6738; }
    { const char * tb_v6739 = "TB_API tb_memb *tb_mem_all = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6739; }
