    { const char * tb_v8174 = "    const uint32_t *src = tb_imgpx + tb_imgs[i].off;\n"; *(const char * *)tb_grow(v_lines) = tb_v8174; }
    { const char * tb_v8175 = "    uint32_t *dst = tb_imgpx + tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8175; }
    { const char * tb_v8176 = "    for (long long y = 0; y < h; y++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8176; }
    { const char * tb_v8177 = "        int y0 = (int)(y * sh / h), y1 = (int)((y + 1) * sh / h);\n"; *(const char * *)tb_grow(v_lines) = tb_v8177; }
    { const char * tb_v8178 = "        if (y1 <= y0) y1 = y0 + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8178; }
    { const char * tb_v8179 = "        for (long long x = 0; x < w; x++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8179; }
    { const char * tb_v8180 = "            int x0 = (int)(x * sw / w), x1 = (int)((x + 1) * sw / w);\n"; *(const char * *)tb_grow(v_lines) = tb_v8180; }
    { const char * tb_v8181 = "            if (x1 <= x0) x1 = x0 + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8181; }
    { const char * tb_v8182 = "            unsigned long long a = 0, r = 0, g = 0, b = 0, n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8182; }
    { const char * tb_v8183 = "            for (int yy = y0; yy < y1; yy++)\n"; *(const char * *)tb_grow(v_lines) = tb_v8183; }
    { const char * tb_v8184 = "                for (int xx = x0; xx < x1; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8184; }
    { const char * tb_v8185 = "                    uint32_t c = src[(size_t)yy * sw + xx];\n"; *(const char * *)tb_grow(v_lines) = tb_v8185; }
    { const char * tb_v8186 = "                    a += c >> 24; r += c >> 16 & 255; g += c >> 8 & 255; b += c & 255; n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8186; }
    { const char * tb_v8187 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v8187; }
    { const char * tb_v8188 = "            dst[(size_t)y * w + x] = (uint32_t)(a / n) << 24 | (uint32_t)(r / n) << 16 | (uint32_t)(g / n) << 8 | (uint32_t)(b / n);\n"; *(const char * *)tb_grow(v_lines) = tb_v8188; }
    { const char * tb_v8189 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8189; }
    { const char * tb_v8190 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8190; }
    { const char * tb_v8191 = "    tb_imgs[tb_nimg].w = (int)w; tb_imgs[tb_nimg].h = (int)h; tb_imgs[tb_nimg].off = (uint32_t)tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8191; }
    { const char * tb_v8192 = "    tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v8192; }
