    { const char * tb_v8212 = "TB_API long long tb_image_w(long long i) { return i >= 0 && i < tb_nimg ? tb_imgs[i].w : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8212; }
    { const char * tb_v8213 = "TB_API long long tb_image_h(long long i) { return i >= 0 && i < tb_nimg ? tb_imgs[i].h : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8213; }
    { const char * tb_v8214 = "// ---------- шрифты TTF: свой чтец (таблицы glyf, без чужих библиотек) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v8214; }
    { const char * tb_v8215 = "// Буква рисуется на процессоре один раз в маленькую картинку с прозрачностью (сглаживание),\n"; *(const char * *)tb_grow(v_lines) = tb_v8215; }
    { const char * tb_v8216 = "// дальше её рисуют и видеокарта, и процессор одинаково: точка = (цвет * a + фон * (255 - a)) / 255.\n"; *(const char * *)tb_grow(v_lines) = tb_v8216; }
    { const char * tb_v8217 = "typedef struct { unsigned char *d; size_t n; uint32_t glyf, loca, hmtx, cmap; int upem, locfmt, nglyphs, nhm, asc, desc, cfmt; } tb_font_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v8217; }
    { const char * tb_v8218 = "TB_API tb_font_t *tb_fonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8218; }
    { const char * tb_v8219 = "TB_API int tb_nfonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8219; }
    { const char * tb_v8220 = "static unsigned tb_u16(const tb_font_t *f, size_t o) { return o + 2 <= f->n ? (unsigned)(f->d[o] << 8 | f->d[o + 1]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8220; }
    { const char * tb_v8221 = "static int tb_s16(const tb_font_t *f, size_t o) { return (int16_t)tb_u16(f, o); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8221; }
    { const char * tb_v8222 = "static uint32_t tb_u32(const tb_font_t *f, size_t o) { return o + 4 <= f->n ? ((uint32_t)f->d[o] << 24 | (uint32_t)f->d[o + 1] << 16 | (uint32_t)f->d[o + 2] << 8 | f->d[o + 3]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8222; }
    { const char * tb_v8223 = "static uint32_t tb_ttf_table(const tb_font_t *f, size_t base, const char *tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8223; }
    { const char * tb_v8224 = "    unsigned n = tb_u16(f, base + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8224; }
    { const char * tb_v8225 = "    for (unsigned i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8225; }
    { const char * tb_v8226 = "        size_t e = base + 12 + 16 * (size_t)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v8226; }
    { const char * tb_v8227 = "        if (e + 16 <= f->n && memcmp(f->d + e, tag, 4) == 0) return tb_u32(f, e + 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v8227; }
    { const char * tb_v8228 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8228; }
    { const char * tb_v8229 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8229; }
    { const char * tb_v8230 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8230; }
    { const char * tb_v8231 = "TB_API void tb_gpu_blend_probe(void);   // TB_GPU_CHECK: проба смешивания букв (ниже)\n"; *(const char * *)tb_grow(v_lines) = tb_v8231; }
    { const char * tb_v8232 = "TB_API long long tb_load_font(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8232; }
    { const char * tb_v8233 = "    FILE *fp = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8233; }
    { const char * tb_v8234 = "    if (!fp) { tb_err = tb_cat(\"нет такого файла шрифта: \", path); return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8234; }
    { const char * tb_v8235 = "    fseek(fp, 0, SEEK_END); long sz = ftell(fp); fseek(fp, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v8235; }
    { const char * tb_v8236 = "    unsigned char *d = sz > 12 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8236; }
    { const char * tb_v8237 = "    if (!d || fread(d, 1, (size_t)sz, fp) != (size_t)sz) { fclose(fp); free(d); tb_err = \"не могу прочитать файл шрифта\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8237; }
    { const char * tb_v8238 = "    fclose(fp);\n"; *(const char * *)tb_grow(v_lines) = tb_v8238; }
    { const char * tb_v8239 = "    tb_font_t f = { d, (size_t)sz };\n"; *(const char * *)tb_grow(v_lines) = tb_v8239; }
    { const char * tb_v8240 = "    size_t base = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8240; }
    { const char * tb_v8241 = "    if (memcmp(d, \"ttcf\", 4) == 0) base = tb_u32(&f, 12);   // сборник шрифтов (.ttc): берём первый\n"; *(const char * *)tb_grow(v_lines) = tb_v8241; }
    { const char * tb_v8242 = "    uint32_t head = tb_ttf_table(&f, base, \"head\"), maxp = tb_ttf_table(&f, base, \"maxp\"), hhea = tb_ttf_table(&f, base, \"hhea\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8242; }
    { const char * tb_v8243 = "    f.glyf = tb_ttf_table(&f, base, \"glyf\"); f.loca = tb_ttf_table(&f, base, \"loca\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8243; }
    { const char * tb_v8244 = "    f.hmtx = tb_ttf_table(&f, base, \"hmtx\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8244; }
    { const char * tb_v8245 = "    uint32_t cmap = tb_ttf_table(&f, base, \"cmap\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8245; }
    { const char * tb_v8246 = "    if (!f.glyf || !f.loca) { free(d); tb_err = \"этот шрифт не TrueType (контуры CFF/OTF пока не читаю): возьми .ttf\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8246; }
    { const char * tb_v8247 = "    if (!head || !maxp || !hhea || !f.hmtx || !cmap) { free(d); tb_err = \"шрифт сломан: нет нужных таблиц\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8247; }
    { const char * tb_v8248 = "    f.upem = (int)tb_u16(&f, head + 18); f.locfmt = tb_s16(&f, head + 50);\n"; *(const char * *)tb_grow(v_lines) = tb_v8248; }
    { const char * tb_v8249 = "    f.nglyphs = (int)tb_u16(&f, maxp + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8249; }
    { const char * tb_v8250 = "    f.asc = tb_s16(&f, hhea + 4); f.desc = tb_s16(&f, hhea + 6); f.nhm = (int)tb_u16(&f, hhea + 34);\n"; *(const char * *)tb_grow(v_lines) = tb_v8250; }
    { const char * tb_v8251 = "    if (f.upem <= 0 || f.nhm <= 0 || f.asc - f.desc <= 0) { free(d); tb_err = \"шрифт сломан: размеры\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8251; }
    { const char * tb_v8252 = "    // буквы → номера глифов: Unicode-таблица формата 12 (все буквы) или 4 (до U+FFFF)\n"; *(const char * *)tb_grow(v_lines) = tb_v8252; }
    { const char * tb_v8253 = "    unsigned nt = tb_u16(&f, cmap + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v8253; }
    { const char * tb_v8254 = "    int best = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8254; }
    { const char * tb_v8255 = "    for (unsigned i = 0; i < nt; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8255; }
    { const char * tb_v8256 = "        size_t e = cmap + 4 + 8 * (size_t)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v8256; }
    { const char * tb_v8257 = "        unsigned pid = tb_u16(&f, e), eid = tb_u16(&f, e + 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v8257; }
    { const char * tb_v8258 = "        uint32_t off = cmap + tb_u32(&f, e + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8258; }
    { const char * tb_v8259 = "        unsigned fmt = tb_u16(&f, off);\n"; *(const char * *)tb_grow(v_lines) = tb_v8259; }
    { const char * tb_v8260 = "        int score = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8260; }
    { const char * tb_v8261 = "        if (fmt == 12 && (pid == 0 || (pid == 3 && eid == 10))) score = 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v8261; }
    { const char * tb_v8262 = "        else if (fmt == 4 && (pid == 0 || (pid == 3 && eid == 1))) score = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8262; }
    { const char * tb_v8263 = "        if (score > best) { best = score; f.cmap = off; f.cfmt = (int)fmt; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8263; }
    { const char * tb_v8264 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8264; }
    { const char * tb_v8265 = "    if (!best) { free(d); tb_err = \"в шрифте нет таблицы букв Unicode\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8265; }
    { const char * tb_v8266 = "    tb_font_t *all = realloc(tb_fonts, (size_t)(tb_nfonts + 1) * sizeof(tb_font_t));\n"; *(const char * *)tb_grow(v_lines) = tb_v8266; }
    { const char * tb_v8267 = "    if (!all) { free(d); tb_err = \"не хватило памяти\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8267; }
    { const char * tb_v8268 = "    tb_fonts = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v8268; }
    { const char * tb_v8269 = "    tb_fonts[tb_nfonts++] = f;\n"; *(const char * *)tb_grow(v_lines) = tb_v8269; }
    { const char * tb_v8270 = "    tb_gpu_blend_probe();\n"; *(const char * *)tb_grow(v_lines) = tb_v8270; }
    { const char * tb_v8271 = "    return tb_nfonts - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8271; }
    { const char * tb_v8272 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8272; }
    { const char * tb_v8273 = "static unsigned tb_ttf_glyph(const tb_font_t *f, unsigned u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8273; }
    { const char * tb_v8274 = "    size_t c = f->cmap;\n"; *(const char * *)tb_grow(v_lines) = tb_v8274; }
    { const char * tb_v8275 = "    if (f->cfmt == 12) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8275; }
    { const char * tb_v8276 = "        uint32_t n = tb_u32(f, c + 12);\n"; *(const char * *)tb_grow(v_lines) = tb_v8276; }
    { const char * tb_v8277 = "        for (uint32_t lo = 0, hi = n; lo < hi;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8277; }
    { const char * tb_v8278 = "            uint32_t mid = (lo + hi) / 2; size_t g = c + 16 + 12 * (size_t)mid;\n"; *(const char * *)tb_grow(v_lines) = tb_v8278; }
    { const char * tb_v8279 = "            uint32_t a = tb_u32(f, g), b = tb_u32(f, g + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v8279; }
    { const char * tb_v8280 = "            if (u < a) hi = mid; else if (u > b) lo = mid + 1; else return tb_u32(f, g + 8) + (u - a);\n"; *(const char * *)tb_grow(v_lines) = tb_v8280; }
    { const char * tb_v8281 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8281; }
    { const char * tb_v8282 = "        return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8282; }
    { const char * tb_v8283 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8283; }
    { const char * tb_v8284 = "    if (u > 0xFFFF) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8284; }
    { const char * tb_v8285 = "    unsigned segs = tb_u16(f, c + 6) / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8285; }
    { const char * tb_v8286 = "    size_t ends = c + 14, starts = ends + 2 * segs + 2, deltas = starts + 2 * segs, ranges = deltas + 2 * segs;\n"; *(const char * *)tb_grow(v_lines) = tb_v8286; }
    { const char * tb_v8287 = "    for (unsigned i = 0; i < segs; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8287; }
    { const char * tb_v8288 = "        if (u > tb_u16(f, ends + 2 * i)) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v8288; }
    { const char * tb_v8289 = "        unsigned s = tb_u16(f, starts + 2 * i);\n"; *(const char * *)tb_grow(v_lines) = tb_v8289; }
    { const char * tb_v8290 = "        if (u < s) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8290; }
    { const char * tb_v8291 = "        unsigned delta = tb_u16(f, deltas + 2 * i), ro = tb_u16(f, ranges + 2 * i);\n"; *(const char * *)tb_grow(v_lines) = tb_v8291; }
    { const char * tb_v8292 = "        if (ro == 0) return (u + delta) & 0xFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v8292; }
    { const char * tb_v8293 = "        unsigned g = tb_u16(f, ranges + 2 * i + ro + 2 * (u - s));\n"; *(const char * *)tb_grow(v_lines) = tb_v8293; }
    { const char * tb_v8294 = "        return g ? (g + delta) & 0xFFFF : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8294; }
    { const char * tb_v8295 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8295; }
    { const char * tb_v8296 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8296; }
    { const char * tb_v8297 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8297; }
    { const char * tb_v8298 = "static double tb_ttf_adv(const tb_font_t *f, unsigned g) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8298; }
    { const char * tb_v8299 = "    unsigned i = (int)g < f->nhm ? g : (unsigned)f->nhm - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8299; }
    { const char * tb_v8300 = "    return tb_u16(f, f->hmtx + 4 * (size_t)i);\n"; *(const char * *)tb_grow(v_lines) = tb_v8300; }
    { const char * tb_v8301 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8301; }
    { const char * tb_v8302 = "static size_t tb_ttf_gpos(const tb_font_t *f, unsigned g, size_t *len) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8302; }
    { const char * tb_v8303 = "    if ((int)g >= f->nglyphs) { *len = 0; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8303; }
