    { const char * tb_v8745 = "            fprintf(stderr, tb_tr(\"TB_GPU_CHECK: кадр %lld: не совпало точек %lld, первая x=%lld y=%lld: видеокарта %06x, процессор %06x\\n\"),\n"; *(const char * *)tb_grow(v_lines) = tb_v8745; }
    { const char * tb_v8746 = "                tb_gpu_frames, bad, first % tb_gw, first / tb_gw, tb_gpu_back[first] & 0xFFFFFF, tb_px[first] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v8746; }
    { const char * tb_v8747 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8747; }
