    { const char * tb_v8796 = "    long long x1 = x + im->w > tb_gw ? tb_gw : x + im->w, y1 = y + im->h > tb_gh ? tb_gh : y + im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v8796; }
    { const char * tb_v8797 = "    tb_gpu_add(x0, y0, x1, y1, x, y, im->off, (3u << 30) | (uint32_t)im->w);\n"; *(const char * *)tb_grow(v_lines) = tb_v8797; }
    { const char * tb_v8798 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8798; }
    { const char * tb_v8799 = "// картинка с настоящей прозрачностью (буквы шрифта): видеокарта смешивает с тем, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v8799; }
    { const char * tb_v8800 = "TB_API void tb_gpu_image_a(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8800; }
    { const char * tb_v8801 = "    tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v8801; }
    { const char * tb_v8802 = "    if (x >= tb_gw || y >= tb_gh || x + im->w <= 0 || y + im->h <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8802; }
    { const char * tb_v8803 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;\n"; *(const char * *)tb_grow(v_lines) = tb_v8803; }
