    { const char * tb_v11834 = "TB_API void tb_ps2_wait_in(void) { for (int i = 0; i < 100000 && (tb_inb(0x64) & 2); i++) {} }\n"; *(const char * *)tb_grow(v_lines) = tb_v11834; }
