    { const char * tb_v11843 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11843; }
    { const char * tb_v11844 = "// «мышь виртуальной машины» (vmmouse в QEMU и VMware): точное место курсора, а не сдвиги —\n"; *(const char * *)tb_grow(v_lines) = tb_v11844; }
    { const char * tb_v11845 = "// мышь не надо «ловить» в окне QEMU. Есть — берём её, нет — обычные пакеты PS/2\n"; *(const char * *)tb_grow(v_lines) = tb_v11845; }
    { const char * tb_v11846 = "TB_API int tb_vmm = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11846; }
    { const char * tb_v11847 = "TB_API void tb_vmm_call(uint32_t cmd, uint32_t arg, uint32_t r[4]) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11847; }
    { const char * tb_v11848 = "    uint32_t a = 0x564D5868u, b = arg, c = cmd, d = 0x5658;\n"; *(const char * *)tb_grow(v_lines) = tb_v11848; }
    { const char * tb_v11849 = "    __asm__ volatile(\"inl %%dx, %%eax\" : \"+a\"(a), \"+b\"(b), \"+c\"(c), \"+d\"(d) : : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v11849; }
    { const char * tb_v11850 = "    r[0] = a; r[1] = b; r[2] = c; r[3] = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v11850; }
    { const char * tb_v11851 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11851; }
