    { const char * tb_v11870 = "        tb_vmm_call(39, 4, r);\n"; *(const char * *)tb_grow(v_lines) = tb_v11870; }
    { const char * tb_v11871 = "        tb_mx = (int)((uint64_t)r[1] * (uint64_t)tb_gw / 65536);\n"; *(const char * *)tb_grow(v_lines) = tb_v11871; }
    { const char * tb_v11872 = "        tb_my = (int)((uint64_t)r[2] * (uint64_t)tb_gh / 65536);\n"; *(const char * *)tb_grow(v_lines) = tb_v11872; }
    { const char * tb_v11873 = "        int down = (r[0] & 0x20) != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11873; }
    { const char * tb_v11874 = "        if (down && !tb_mdown) tb_mtap = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11874; }
    { const char * tb_v11875 = "        tb_mdown = down;\n"; *(const char * *)tb_grow(v_lines) = tb_v11875; }
