    { const char * tb_v11891 = "    if (tb_mpk[0] & 0xC0) dx = dy = 0;            // переполнение: пакет не верен\n"; *(const char * *)tb_grow(v_lines) = tb_v11891; }
    { const char * tb_v11892 = "    tb_mx += dx; tb_my -= dy;\n"; *(const char * *)tb_grow(v_lines) = tb_v11892; }
    { const char * tb_v11893 = "    if (tb_mx < 0) tb_mx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11893; }
    { const char * tb_v11894 = "    if (tb_my < 0) tb_my = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11894; }
    { const char * tb_v11895 = "    if (tb_mx >= tb_gw) tb_mx = tb_gw - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11895; }
    { const char * tb_v11896 = "    if (tb_my >= tb_gh) tb_my = tb_gh - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11896; }
    { const char * tb_v11897 = "    int down = tb_mpk[0] & 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11897; }
    { const char * tb_v11898 = "    if (down && !tb_mdown) tb_mtap = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11898; }
    { const char * tb_v11899 = "    tb_mdown = down;\n"; *(const char * *)tb_grow(v_lines) = tb_v11899; }
