    { const char * tb_v11904 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11904; }
    { const char * tb_v11905 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11905; }
    { const char * tb_v11906 = "TB_API void tb_mouse_init(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11906; }
    { const char * tb_v11907 = "    uint64_t f = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v11907; }
    { const char * tb_v11908 = "    tb_ps2_wait_in(); tb_outb(0x64, 0xA8);        // включить вход мыши\n"; *(const char * *)tb_grow(v_lines) = tb_v11908; }
