    { const char * tb_v11912 = "        cfg = (cfg | 2) & ~0x20;                   // прерывание мыши есть, часы мыши идут\n"; *(const char * *)tb_grow(v_lines) = tb_v11912; }
    { const char * tb_v11913 = "        tb_ps2_wait_in(); tb_outb(0x64, 0x60);\n"; *(const char * *)tb_grow(v_lines) = tb_v11913; }
    { const char * tb_v11914 = "        tb_ps2_wait_in(); tb_outb(0x60, (unsigned char)cfg);\n"; *(const char * *)tb_grow(v_lines) = tb_v11914; }
