    { const char * tb_v13486 = "        if (tb_wn > 1) { int w = tb_wfind((uintptr_t)e.xany.window); if (w >= 0) tb_wswitch(w); }   // событие другого окна\n"; *(const char * *)tb_grow(v_lines) = tb_v13486; }
    { const char * tb_v13487 = "        if (e.type == SelectionRequest) tb_x_clip_answer(&e.xselectionrequest);\n"; *(const char * *)tb_grow(v_lines) = tb_v13487; }
    { const char * tb_v13488 = "        else if (e.type == FocusOut) memset(tb_keys, 0, sizeof tb_keys);\n"; *(const char * *)tb_grow(v_lines) = tb_v13488; }
    { const char * tb_v13489 = "        else if (e.type == ClientMessage && (Atom)e.xclient.data.l[0] == tb_wm_del) tb_gclosed = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13489; }
    { const char * tb_v13490 = "        else if (e.type == KeyPress || e.type == KeyRelease) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13490; }
    { const char * tb_v13491 = "            int k = tb_x_key(XLookupKeysym(&e.xkey, 0));\n"; *(const char * *)tb_grow(v_lines) = tb_v13491; }
    { const char * tb_v13492 = "            if (k) { tb_keys[k] = e.type == KeyPress; if (tb_keys[k]) tb_ktap[k] = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13492; }
    { const char * tb_v13493 = "            if (e.type == KeyPress) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13493; }
    { const char * tb_v13494 = "                char buf[16]; KeySym ks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13494; }
    { const char * tb_v13495 = "                XLookupString(&e.xkey, buf, sizeof buf, &ks, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v13495; }
    { const char * tb_v13496 = "                if (!(e.xkey.state & ControlMask)) tb_type_cp(tb_x_uni(ks));\n"; *(const char * *)tb_grow(v_lines) = tb_v13496; }
    { const char * tb_v13497 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v13497; }
    { const char * tb_v13498 = "        } else if (e.type == ButtonPress || e.type == ButtonRelease) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13498; }
    { const char * tb_v13499 = "            if (e.xbutton.button == 1) { tb_mdown = e.type == ButtonPress; if (tb_mdown) tb_mtap = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13499; }
    { const char * tb_v13500 = "            if (e.xbutton.button == 8 || e.xbutton.button == 9) tb_side(e.xbutton.button - 8, e.type == ButtonPress);\n"; *(const char * *)tb_grow(v_lines) = tb_v13500; }
    { const char * tb_v13501 = "            if (e.type == ButtonPress && e.xbutton.button == 4) tb_wheel_add(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v13501; }
    { const char * tb_v13502 = "            if (e.type == ButtonPress && e.xbutton.button == 5) tb_wheel_add(-1);\n"; *(const char * *)tb_grow(v_lines) = tb_v13502; }
    { const char * tb_v13503 = "            tb_mx = e.xbutton.x; tb_my = e.xbutton.y;\n"; *(const char * *)tb_grow(v_lines) = tb_v13503; }
    { const char * tb_v13504 = "        } else if (e.type == MotionNotify) tb_mouse_at(e.xmotion.x, e.xmotion.y);\n"; *(const char * *)tb_grow(v_lines) = tb_v13504; }
    { const char * tb_v13505 = "        else if (e.type == ConfigureNotify && (e.xconfigure.width != tb_gw || e.xconfigure.height != tb_gh)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13505; }
    { const char * tb_v13506 = "            tb_new_w = e.xconfigure.width; tb_new_h = e.xconfigure.height;\n"; *(const char * *)tb_grow(v_lines) = tb_v13506; }
    { const char * tb_v13507 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v13507; }
    { const char * tb_v13508 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13508; }
    { const char * tb_v13509 = "    if (tb_wcur != was) tb_wswitch(was);\n"; *(const char * *)tb_grow(v_lines) = tb_v13509; }
    { const char * tb_v13510 = "    if (tb_mlock && tb_mwarp) { XWarpPointer(tb_dpy, None, tb_xw, 0, 0, 0, 0, tb_gw / 2, tb_gh / 2); tb_mwarp = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13510; }
    { const char * tb_v13511 = "    XFlush(tb_dpy);\n"; *(const char * *)tb_grow(v_lines) = tb_v13511; }
    { const char * tb_v13512 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13512; }
    { const char * tb_v13513 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v13513; }
    { const char * tb_v13514 = "// TB_GPU_CHECK: проба смешивания. Видеокарты считают смешивание по-своему (AMD на Mac — с малой\n"; *(const char * *)tb_grow(v_lines) = tb_v13514; }
    { const char * tb_v13515 = "// точностью, ошибка зависит и от цвета буквы, и от фона), поэтому проба берёт все сочетания:\n"; *(const char * *)tb_grow(v_lines) = tb_v13515; }
    { const char * tb_v13516 = "// цвет c, фон d, прозрачность a — 256 × 256 × 256 точек, кадр за кадром, и процессор дальше\n"; *(const char * *)tb_grow(v_lines) = tb_v13516; }
    { const char * tb_v13517 = "// смешивает по этой таблице (tb_blend_lut[c][d][a]). Делается один раз, когда есть и окно, и шрифт.\n"; *(const char * *)tb_grow(v_lines) = tb_v13517; }
    { const char * tb_v13518 = "// После пробы кадр видеокарты снова становится таким же, как у процессора (копия tb_px)\n"; *(const char * *)tb_grow(v_lines) = tb_v13518; }
    { const char * tb_v13519 = "TB_API void tb_gpu_blend_probe(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13519; }
    { const char * tb_v13520 = "    if (!tb_gpu_on || !tb_gpu_check || tb_blend_cal || !tb_px || !tb_nfonts) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13520; }
    { const char * tb_v13521 = "    uint8_t *lut = malloc((size_t)1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v13521; }
    { const char * tb_v13522 = "    if (!lut) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13522; }
    { const char * tb_v13523 = "    size_t n = (size_t)tb_gw * tb_gh, p0 = tb_imgpx_n, need = p0 + 3 * n;\n"; *(const char * *)tb_grow(v_lines) = tb_v13523; }
    { const char * tb_v13524 = "    int n0 = tb_nimg;\n"; *(const char * *)tb_grow(v_lines) = tb_v13524; }
    { const char * tb_v13525 = "    uint32_t *all = need <= 0xFFFFFFFFu ? realloc(tb_imgpx, need * 4) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13525; }
    { const char * tb_v13526 = "    tb_image *list = realloc(tb_imgs, (size_t)(n0 + 3) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v13526; }
    { const char * tb_v13527 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v13527; }
    { const char * tb_v13528 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v13528; }
    { const char * tb_v13529 = "    if (!all || !list) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13529; }
    { const char * tb_v13530 = "    for (int k = 0; k < 3; k++) { tb_imgs[n0 + k].w = tb_gw; tb_imgs[n0 + k].h = tb_gh; tb_imgs[n0 + k].off = (uint32_t)(p0 + k * n); }\n"; *(const char * *)tb_grow(v_lines) = tb_v13530; }
    { const char * tb_v13531 = "    tb_nimg = n0 + 3; tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v13531; }
    { const char * tb_v13532 = "    uint32_t *keep = tb_imgpx + p0 + 2 * n;   // кадр процессора: вернуть его видеокарте после пробы\n"; *(const char * *)tb_grow(v_lines) = tb_v13532; }
    { const char * tb_v13533 = "    for (size_t q = 0; q < n; q++) keep[q] = 0xFF000000u | tb_px[q];\n"; *(const char * *)tb_grow(v_lines) = tb_v13533; }
    { const char * tb_v13534 = "    tb_gpu_probing = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13534; }
    { const char * tb_v13535 = "    int ok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13535; }
    { const char * tb_v13536 = "    for (size_t from = 0; from < ((size_t)1 << 24) && ok; from += n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13536; }
    { const char * tb_v13537 = "        uint32_t *bg = tb_imgpx + p0, *fg = bg + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v13537; }
    { const char * tb_v13538 = "        for (size_t q = 0; q < n; q++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13538; }
    { const char * tb_v13539 = "            size_t i = (from + q) & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v13539; }
    { const char * tb_v13540 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v13540; }
    { const char * tb_v13541 = "            bg[q] = 0xFF000000u | d * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v13541; }
    { const char * tb_v13542 = "            fg[q] = (a << 24) | c * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v13542; }
    { const char * tb_v13543 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v13543; }
    { const char * tb_v13544 = "        tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13544; }
    { const char * tb_v13545 = "        tb_gpu_image(n0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v13545; }
    { const char * tb_v13546 = "        tb_gpu_image_a(n0 + 1, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v13546; }
    { const char * tb_v13547 = "        tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v13547; }
    { const char * tb_v13548 = "        if (!tb_gpu_back) { ok = 0; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13548; }
    { const char * tb_v13549 = "        for (size_t q = 0; q < n && from + q < ((size_t)1 << 24); q++) lut[from + q] = (uint8_t)(tb_gpu_back[q] & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v13549; }
    { const char * tb_v13550 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13550; }
    { const char * tb_v13551 = "    tb_gpu_image(n0 + 2, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v13551; }
    { const char * tb_v13552 = "    tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v13552; }
    { const char * tb_v13553 = "    tb_gpu_probing = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13553; }
    { const char * tb_v13554 = "    tb_nimg = n0; tb_imgpx_n = p0; tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13554; }
    { const char * tb_v13555 = "    if (!ok) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13555; }
    { const char * tb_v13556 = "    tb_blend_lut = lut;\n"; *(const char * *)tb_grow(v_lines) = tb_v13556; }
    { const char * tb_v13557 = "    tb_blend_cal = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13557; }
    { const char * tb_v13558 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v13558; }
    { const char * tb_v13559 = "    if (e && e[0] == '1') {\n"; *(const char * *)tb_grow(v_lines) = tb_v13559; }
    { const char * tb_v13560 = "        long long diff = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13560; }
    { const char * tb_v13561 = "        for (size_t i = 0; i < ((size_t)1 << 24); i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13561; }
    { const char * tb_v13562 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v13562; }
    { const char * tb_v13563 = "            uint32_t w = a == 0 ? d : (c * a + 127) / 255 + (d * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v13563; }
    { const char * tb_v13564 = "            diff += lut[i] != w;\n"; *(const char * *)tb_grow(v_lines) = tb_v13564; }
    { const char * tb_v13565 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v13565; }
    { const char * tb_v13566 = "        fprintf(stderr, tb_tr(\"TB_GPU_CHECK: смешивание на этой видеокарте не как округление к ближайшему: %lld из %d\\n\"), diff, 1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v13566; }
    { const char * tb_v13567 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13567; }
    { const char * tb_v13568 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13568; }
    { const char * tb_v13569 = "// window_sharp(): окно в настоящих точках экрана (Retina, 150% и 200% на Windows). Размер в window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v13569; }
    { const char * tb_v13570 = "// остаётся в «обычных» точках, а кадр, window_w/h и мышь — в настоящих; window_scale() — во сколько раз\n"; *(const char * *)tb_grow(v_lines) = tb_v13570; }
    { const char * tb_v13571 = "TB_API double tb_gfx_scale(void);   // своя у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v13571; }
    { const char * tb_v13572 = "TB_API void tb_window_sharp(void) { if (!tb_px) tb_sharp = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13572; }
    { const char * tb_v13573 = "TB_API double tb_window_scale(void) { return tb_sc; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13573; }
    { const char * tb_v13574 = "// ---- несколько окон (1.3): window_new, window_use, window_close, window_shown ----\n"; *(const char * *)tb_grow(v_lines) = tb_v13574; }
    { const char * tb_v13575 = "// Главное окно (window_open) — номер 0. У каждого окна свои точки, размер, мышь, клавиши и глубина 3D.\n"; *(const char * *)tb_grow(v_lines) = tb_v13575; }
    { const char * tb_v13576 = "// Текущее окно лежит в обычных переменных (tb_px, tb_gw, tb_keys ...), остальные ждут в tb_wins.\n"; *(const char * *)tb_grow(v_lines) = tb_v13576; }
    { const char * tb_v13577 = "// Новые окна рисует процессор; видеокарта — у главного окна\n"; *(const char * *)tb_grow(v_lines) = tb_v13577; }
    { const char * tb_v13578 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v13578; }
    { const char * tb_v13579 = "    int used;\n"; *(const char * *)tb_grow(v_lines) = tb_v13579; }
    { const char * tb_v13580 = "    uint32_t *px; int gw, gh, gclosed, mx, my, mdown, mtap, wheel; double wheel_f;\n"; *(const char * *)tb_grow(v_lines) = tb_v13580; }
    { const char * tb_v13581 = "    int mside[2], mside_tap[2], ntyped; char typed[512];\n"; *(const char * *)tb_grow(v_lines) = tb_v13581; }
    { const char * tb_v13582 = "    unsigned char keys[256], ktap[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v13582; }
    { const char * tb_v13583 = "    int new_w, new_h, resizable, gpu_on, zclr, gzclr; uint32_t *zb; long long zb_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v13583; }
    { const char * tb_v13584 = "    TB_WPLAT\n"; *(const char * *)tb_grow(v_lines) = tb_v13584; }
    { const char * tb_v13585 = "} tb_wslot;\n"; *(const char * *)tb_grow(v_lines) = tb_v13585; }
    { const char * tb_v13586 = "static tb_wslot tb_wins[TB_WMAX];\n"; *(const char * *)tb_grow(v_lines) = tb_v13586; }
    { const char * tb_v13587 = "#define TB_WFIELDS(X) X(px, tb_px) X(gw, tb_gw) X(gh, tb_gh) X(gclosed, tb_gclosed) X(mx, tb_mx) X(my, tb_my) \\\n"; *(const char * *)tb_grow(v_lines) = tb_v13587; }
    { const char * tb_v13588 = "    X(mdown, tb_mdown) X(mtap, tb_mtap) X(wheel, tb_wheel) X(wheel_f, tb_wheel_f) X(ntyped, tb_ntyped) \\\n"; *(const char * *)tb_grow(v_lines) = tb_v13588; }
    { const char * tb_v13589 = "    X(new_w, tb_new_w) X(new_h, tb_new_h) X(resizable, tb_resizable) X(gpu_on, tb_gpu_on) X(zclr, tb_zclr) \\\n"; *(const char * *)tb_grow(v_lines) = tb_v13589; }
    { const char * tb_v13590 = "    X(gzclr, tb_gzclr) X(zb, tb_zb) X(zb_n, tb_zb_n)\n"; *(const char * *)tb_grow(v_lines) = tb_v13590; }
    { const char * tb_v13591 = "#define TB_WSAVE1(f, g) s->f = g;\n"; *(const char * *)tb_grow(v_lines) = tb_v13591; }
    { const char * tb_v13592 = "#define TB_WLOAD1(f, g) g = s->f;\n"; *(const char * *)tb_grow(v_lines) = tb_v13592; }
    { const char * tb_v13593 = "static void tb_wsave(tb_wslot *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13593; }
    { const char * tb_v13594 = "    TB_WFIELDS(TB_WSAVE1)\n"; *(const char * *)tb_grow(v_lines) = tb_v13594; }
    { const char * tb_v13595 = "    memcpy(s->mside, tb_mside, sizeof s->mside); memcpy(s->mside_tap, tb_mside_tap, sizeof s->mside_tap);\n"; *(const char * *)tb_grow(v_lines) = tb_v13595; }
    { const char * tb_v13596 = "    memcpy(s->typed, tb_typed, sizeof s->typed); memcpy(s->keys, tb_keys, sizeof s->keys); memcpy(s->ktap, tb_ktap, sizeof s->ktap);\n"; *(const char * *)tb_grow(v_lines) = tb_v13596; }
    { const char * tb_v13597 = "    TB_WPLAT_SAVE(s)\n"; *(const char * *)tb_grow(v_lines) = tb_v13597; }
    { const char * tb_v13598 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13598; }
    { const char * tb_v13599 = "static void tb_wload(tb_wslot *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13599; }
    { const char * tb_v13600 = "    TB_WFIELDS(TB_WLOAD1)\n"; *(const char * *)tb_grow(v_lines) = tb_v13600; }
    { const char * tb_v13601 = "    memcpy(tb_mside, s->mside, sizeof s->mside); memcpy(tb_mside_tap, s->mside_tap, sizeof s->mside_tap);\n"; *(const char * *)tb_grow(v_lines) = tb_v13601; }
    { const char * tb_v13602 = "    memcpy(tb_typed, s->typed, sizeof s->typed); memcpy(tb_keys, s->keys, sizeof s->keys); memcpy(tb_ktap, s->ktap, sizeof s->ktap);\n"; *(const char * *)tb_grow(v_lines) = tb_v13602; }
    { const char * tb_v13603 = "    TB_WPLAT_LOAD(s)\n"; *(const char * *)tb_grow(v_lines) = tb_v13603; }
    { const char * tb_v13604 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13604; }
    { const char * tb_v13605 = "TB_API int tb_wfind(uintptr_t h) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13605; }
    { const char * tb_v13606 = "    for (int i = 0; i < tb_wn; i++) if (tb_wins[i].used && tb_whand[i] == h && h) return i;\n"; *(const char * *)tb_grow(v_lines) = tb_v13606; }
    { const char * tb_v13607 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13607; }
    { const char * tb_v13608 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13608; }
    { const char * tb_v13609 = "// сделать окно i текущим: 3D, которое ждало, дорисовывается в прежнее окно\n"; *(const char * *)tb_grow(v_lines) = tb_v13609; }
    { const char * tb_v13610 = "TB_API void tb_wswitch(int i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13610; }
    { const char * tb_v13611 = "    if (i == tb_wcur || i < 0 || i >= tb_wn || !tb_wins[i].used) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13611; }
    { const char * tb_v13612 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v13612; }
    { const char * tb_v13613 = "    tb_wsave(&tb_wins[tb_wcur]);\n"; *(const char * *)tb_grow(v_lines) = tb_v13613; }
    { const char * tb_v13614 = "    tb_wload(&tb_wins[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v13614; }
    { const char * tb_v13615 = "    tb_wcur = i;\n"; *(const char * *)tb_grow(v_lines) = tb_v13615; }
