    { const char * tb_v13767 = "    if (nosync != tb_gpu_nosync) { tb_gpu_nosync = nosync; if (tb_gpu_on) tb_gpu_vsync(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v13767; }
    { const char * tb_v13768 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13768; }
