    { const char * tb_v13770 = "TB_API long long tb_fps(void) { return tb_fps_v ? tb_fps_v : tb_frame_ms_v > 0 ? (long long)(1000 / tb_frame_ms_v) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13770; }
    { const char * tb_v13771 = "// показать кадр, принять клавиши и мышь, держать частоту кадров; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v13771; }
    { const char * tb_v13772 = "TB_API int tb_window_alive(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13772; }
    { const char * tb_v13773 = "    if (tb_wn > 1) tb_windows_show();\n"; *(const char * *)tb_grow(v_lines) = tb_v13773; }
    { const char * tb_v13774 = "    if (!tb_px || tb_gclosed) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13774; }
    { const char * tb_v13775 = "    TB_SCENE();        // сцена 3D, которая ждала (тени, прозрачные) — в этот кадр\n"; *(const char * *)tb_grow(v_lines) = tb_v13775; }
    { const char * tb_v13776 = "    tb_gfx_events();   // здесь показывается прошлый кадр\n"; *(const char * *)tb_grow(v_lines) = tb_v13776; }
    { const char * tb_v13777 = "    if (tb_wn > 1) tb_windows_after();\n"; *(const char * *)tb_grow(v_lines) = tb_v13777; }
    { const char * tb_v13778 = "    tb_zclr = tb_gzclr = 1;   // новый кадр: глубина 3D начинается заново\n"; *(const char * *)tb_grow(v_lines) = tb_v13778; }
    { const char * tb_v13779 = "    tb_apply_resize();\n"; *(const char * *)tb_grow(v_lines) = tb_v13779; }
    { const char * tb_v13780 = "    // TB_FPS_FREE=1 — без ограничения (для замеров скорости), как set_fps(0)\n"; *(const char * *)tb_grow(v_lines) = tb_v13780; }
    { const char * tb_v13781 = "    static int free_fps = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v13781; }
    { const char * tb_v13782 = "    if (free_fps < 0) free_fps = getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13782; }
    { const char * tb_v13783 = "    long long now = tb_time_us(), period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13783; }
    { const char * tb_v13784 = "    if (!tb_last_us) tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v13784; }
    { const char * tb_v13785 = "    if (free_fps || tb_fps_want == 0) period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13785; }
    { const char * tb_v13786 = "    else if (tb_fps_want > 0) period = 1000000 / tb_fps_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v13786; }
    { const char * tb_v13787 = "    // как у экрана: видеокарта сама ждёт обновления экрана (60 Гц — 60 кадров, 120 Гц — 120);\n"; *(const char * *)tb_grow(v_lines) = tb_v13787; }
    { const char * tb_v13788 = "    // кадр пришёл быстрее 4 мс — экран частоту не держит, держим сами 60 кадров в секунду\n"; *(const char * *)tb_grow(v_lines) = tb_v13788; }
    { const char * tb_v13789 = "    else if (!tb_gpu_on || now - tb_last_us < 4000) period = 16667;\n"; *(const char * *)tb_grow(v_lines) = tb_v13789; }
    { const char * tb_v13790 = "    if (period && now - tb_last_us < period) { usleep((useconds_t)(period - (now - tb_last_us))); now = tb_time_us(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v13790; }
    { const char * tb_v13791 = "    tb_frame_ms_v = (now - tb_last_us) / 1000.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13791; }
    { const char * tb_v13792 = "    tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v13792; }
    { const char * tb_v13793 = "    if (!tb_fps_t0) tb_fps_t0 = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v13793; }
    { const char * tb_v13794 = "    tb_fps_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v13794; }
    { const char * tb_v13795 = "    if (now - tb_fps_t0 >= 1000000) { tb_fps_v = tb_fps_n * 1000000 / (now - tb_fps_t0); tb_fps_n = 0; tb_fps_t0 = now; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13795; }
    { const char * tb_v13796 = "    tb_last_frame = now / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v13796; }
