    { const char * tb_v13800 = "    if (tb_px && x >= 0 && y >= 0 && x < tb_gw && y < tb_gh) tb_px[y * tb_gw + x] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v13800; }
    { const char * tb_v13801 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13801; }
    { const char * tb_v13802 = "// на видеокарте фигуры записываются (tb_gpu_*), на процессоре — рисуются сразу в tb_px.\n"; *(const char * *)tb_grow(v_lines) = tb_v13802; }
    { const char * tb_v13803 = "// TB_GPU_CHECK=1: и то и другое, кадры сверяются\n"; *(const char * *)tb_grow(v_lines) = tb_v13803; }
    { const char * tb_v13804 = "#define TB_CPU_DRAW (!tb_gpu_on || tb_gpu_check)\n"; *(const char * *)tb_grow(v_lines) = tb_v13804; }
    { const char * tb_v13805 = "TB_API long long tb_mdrawn = 0, tb_mdrawn_last = 0;   // сколько draw_mesh дошло до рисования (не отсечено) в кадре\n"; *(const char * *)tb_grow(v_lines) = tb_v13805; }
    { const char * tb_v13806 = "TB_API void tb_clear_window(long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13806; }
    { const char * tb_v13807 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v13807; }
    { const char * tb_v13808 = "    tb_mdrawn_last = tb_mdrawn; tb_mdrawn = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13808; }
    { const char * tb_v13809 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13809; }
    { const char * tb_v13810 = "    if (tb_gpu_on) { tb_gin = 0; tb_gpu_rect(0, 0, tb_gw, tb_gh, c); }   // всё прежнее закрашено\n"; *(const char * *)tb_grow(v_lines) = tb_v13810; }
    { const char * tb_v13811 = "    if (TB_CPU_DRAW) for (long long i = 0; i < (long long)tb_gw * tb_gh; i++) tb_px[i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v13811; }
    { const char * tb_v13812 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13812; }
    { const char * tb_v13813 = "TB_API void tb_draw_pixel(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13813; }
    { const char * tb_v13814 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v13814; }
