    { const char * tb_v13816 = "    if (tb_gpu_on) tb_gpu_rect(x, y, 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v13816; }
    { const char * tb_v13817 = "    if (TB_CPU_DRAW) tb_put(x, y, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v13817; }
    { const char * tb_v13818 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13818; }
    { const char * tb_v13819 = "// полупрозрачный цвет (rgba): в старшем байте — прозрачность 1..255 (0 — непрозрачный, как у rgb)\n"; *(const char * *)tb_grow(v_lines) = tb_v13819; }
    { const char * tb_v13820 = "TB_INL uint32_t tb_mix(uint32_t d, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13820; }
    { const char * tb_v13821 = "    uint32_t t = (c >> 24) & 255, a = 255 - t;\n"; *(const char * *)tb_grow(v_lines) = tb_v13821; }
    { const char * tb_v13822 = "    uint32_t rb = ((c & 0xFF00FF) * a + (d & 0xFF00FF) * t + 0x800080) >> 8 & 0xFF00FF;\n"; *(const char * *)tb_grow(v_lines) = tb_v13822; }
    { const char * tb_v13823 = "    uint32_t g = ((c & 0x00FF00) * a + (d & 0x00FF00) * t + 0x008000) >> 8 & 0x00FF00;\n"; *(const char * *)tb_grow(v_lines) = tb_v13823; }
    { const char * tb_v13824 = "    return rb | g;\n"; *(const char * *)tb_grow(v_lines) = tb_v13824; }
    { const char * tb_v13825 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13825; }
    { const char * tb_v13826 = "TB_API void tb_cpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13826; }
    { const char * tb_v13827 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v13827; }
    { const char * tb_v13828 = "    if ((c >> 24) & 255) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13828; }
    { const char * tb_v13829 = "        for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], (uint32_t)c);\n"; *(const char * *)tb_grow(v_lines) = tb_v13829; }
    { const char * tb_v13830 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13830; }
    { const char * tb_v13831 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13831; }
    { const char * tb_v13832 = "    for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v13832; }
    { const char * tb_v13833 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13833; }
    { const char * tb_v13834 = "TB_API void tb_draw_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13834; }
    { const char * tb_v13835 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v13835; }
    { const char * tb_v13836 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13836; }
    { const char * tb_v13837 = "    if (tb_gpu_on) tb_gpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v13837; }
