    { const char * tb_v13839 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13839; }
    { const char * tb_v13840 = "// точка с покрытием cov (0..1): цвет c (может быть rgba) смешивается с тем, что под ним\n"; *(const char * *)tb_grow(v_lines) = tb_v13840; }
    { const char * tb_v13841 = "TB_INL void tb_cover(long long x, long long y, uint32_t c, double cov) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13841; }
    { const char * tb_v13842 = "    if (x < 0 || y < 0 || x >= tb_gw || y >= tb_gh || cov <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13842; }
    { const char * tb_v13843 = "    uint32_t a = 255 - ((c >> 24) & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v13843; }
    { const char * tb_v13844 = "    a = (uint32_t)(a * (cov > 1 ? 1 : cov) + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v13844; }
    { const char * tb_v13845 = "    if (a == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13845; }
