    { const char * tb_v13897 = "// прямоугольник со скруглёнными углами, края сглажены; цвет может быть полупрозрачным (rgba)\n"; *(const char * *)tb_grow(v_lines) = tb_v13897; }
    { const char * tb_v13898 = "TB_API void tb_draw_round(long long x, long long y, long long w, long long h, long long r, const char *corners, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13898; }
    { const char * tb_v13899 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v13899; }
