    { const char * tb_v13953 = "        sb += (long long)(in & 255) - (out & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v13953; }
    { const char * tb_v13954 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13954; }
