    { const char * tb_v13984 = "    if (half)\n"; *(const char * *)tb_grow(v_lines) = tb_v13984; }
    { const char * tb_v13985 = "        // обратно: каждая точка — смесь четырёх соседних из маленькой картинки\n"; *(const char * *)tb_grow(v_lines) = tb_v13985; }
    { const char * tb_v13986 = "        for (long long yy = 0; yy < H; yy++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13986; }
    { const char * tb_v13987 = "            long long fy = yy * 128 - 64; if (fy < 0) fy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13987; }
    { const char * tb_v13988 = "            long long iy = fy >> 8, ty = fy & 255, iy2 = iy + 1 < bh ? iy + 1 : iy;\n"; *(const char * *)tb_grow(v_lines) = tb_v13988; }
    { const char * tb_v13989 = "            for (long long xx = 0; xx < W; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13989; }
