    { const char * tb_v14001 = "        for (long long yy = 0; yy < bh; yy++) memcpy(tb_px + (y0 + yy) * tb_gw + x0, b + yy * bw, (size_t)bw * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v14001; }
    { const char * tb_v14002 = "    free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v14002; }
    { const char * tb_v14003 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14003; }
    { const char * tb_v14004 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14004; }
    { const char * tb_v14005 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14005; }
    { const char * tb_v14006 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14006; }
    { const char * tb_v14007 = "    if (tb_gpu_on) tb_gpu_circle(cx, cy, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14007; }
    { const char * tb_v14008 = "    if (TB_CPU_DRAW) {   // только строки и столбцы внутри окна: огромный круг не перебирает r*r точек\n"; *(const char * *)tb_grow(v_lines) = tb_v14008; }
    { const char * tb_v14009 = "        long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v14009; }
