    { const char * tb_v14023 = "    int gpu = tb_gpu_on, cpu = TB_CPU_DRAW;\n"; *(const char * *)tb_grow(v_lines) = tb_v14023; }
    { const char * tb_v14024 = "    while (1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14024; }
    { const char * tb_v14025 = "        if (gpu) tb_gpu_rect(x0, y0, 1, 1, c);   // соседние точки склеятся в полоски\n"; *(const char * *)tb_grow(v_lines) = tb_v14025; }
    { const char * tb_v14026 = "        if (cpu) tb_put(x0, y0, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v14026; }
    { const char * tb_v14027 = "        if (x0 == x1 && y0 == y1) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v14027; }
    { const char * tb_v14028 = "        long long e2 = 2 * e;\n"; *(const char * *)tb_grow(v_lines) = tb_v14028; }
    { const char * tb_v14029 = "        if (e2 >= dy) { e += dy; x0 += sx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14029; }
    { const char * tb_v14030 = "        if (e2 <= dx) { e += dx; y0 += sy; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14030; }
    { const char * tb_v14031 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14031; }
    { const char * tb_v14032 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14032; }
    { const char * tb_v14033 = "// Треугольник. Правило точек одно для процессора и видеокарты (кадры совпадают точка в точку):\n"; *(const char * *)tb_grow(v_lines) = tb_v14033; }
    { const char * tb_v14034 = "// точка (x, y) берётся по своему центру (x + 0.5, y + 0.5); углы обходятся так, что площадь > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14034; }
    { const char * tb_v14035 = "// для каждой стороны a→b: e = (bx-ax)*(2y+1-2ay) - (by-ay)*(2x+1-2ax); точка внутри, если e > 0\n"; *(const char * *)tb_grow(v_lines) = tb_v14035; }
    { const char * tb_v14036 = "// для всех трёх, а если e == 0 — только на сторонах с by > ay или (by == ay и bx < ax).\n"; *(const char * *)tb_grow(v_lines) = tb_v14036; }
    { const char * tb_v14037 = "// Так у двух соседних треугольников общая сторона рисуется ровно один раз.\n"; *(const char * *)tb_grow(v_lines) = tb_v14037; }
    { const char * tb_v14038 = "// Углы дальше ±8192 точек: треугольник сначала обрезается рамкой вокруг окна (tb_poly_draw) —\n"; *(const char * *)tb_grow(v_lines) = tb_v14038; }
    { const char * tb_v14039 = "// тогда в шейдере (32-битные числа) ничего не переполняется.\n"; *(const char * *)tb_grow(v_lines) = tb_v14039; }
    { const char * tb_v14040 = "TB_INL long long tb_tri_clamp(long long v) { return v < -8192 ? -8192 : v > 8192 ? 8192 : v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14040; }
    { const char * tb_v14041 = "// t = x1 y1 x2 y2 x3 y3; 0 — рисовать нечего (площадь 0 или целиком вне окна)\n"; *(const char * *)tb_grow(v_lines) = tb_v14041; }
    { const char * tb_v14042 = "TB_INL int tb_tri_prep(long long *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14042; }
    { const char * tb_v14043 = "    for (int i = 0; i < 6; i++) t[i] = tb_tri_clamp(t[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v14043; }
    { const char * tb_v14044 = "    long long a2 = (t[2] - t[0]) * (t[5] - t[1]) - (t[3] - t[1]) * (t[4] - t[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v14044; }
    { const char * tb_v14045 = "    if (a2 == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14045; }
    { const char * tb_v14046 = "    if (a2 < 0) { long long x = t[2], y = t[3]; t[2] = t[4]; t[3] = t[5]; t[4] = x; t[5] = y; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14046; }
    { const char * tb_v14047 = "    long long x0 = t[0], x1 = t[0], y0 = t[1], y1 = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v14047; }
    { const char * tb_v14048 = "    for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14048; }
    { const char * tb_v14049 = "        if (t[i] < x0) x0 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v14049; }
    { const char * tb_v14050 = "        if (t[i] > x1) x1 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v14050; }
    { const char * tb_v14051 = "        if (t[i + 1] < y0) y0 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v14051; }
    { const char * tb_v14052 = "        if (t[i + 1] > y1) y1 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v14052; }
    { const char * tb_v14053 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14053; }
    { const char * tb_v14054 = "    return !(x1 < 0 || y1 < 0 || x0 > tb_gw || y0 > tb_gh);\n"; *(const char * *)tb_grow(v_lines) = tb_v14054; }
    { const char * tb_v14055 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14055; }
    { const char * tb_v14056 = "TB_INL int tb_tri_edge(long long ax, long long ay, long long bx, long long by, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14056; }
    { const char * tb_v14057 = "    long long ex = bx - ax, ey = by - ay, e = ex * (2 * y + 1 - 2 * ay) - ey * (2 * x + 1 - 2 * ax);\n"; *(const char * *)tb_grow(v_lines) = tb_v14057; }
    { const char * tb_v14058 = "    return e > 0 || (e == 0 && (ey > 0 || (ey == 0 && ex < 0)));\n"; *(const char * *)tb_grow(v_lines) = tb_v14058; }
    { const char * tb_v14059 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14059; }
    { const char * tb_v14060 = "// глубина точки (x, y) по плоскости треугольника — так же, как в шейдере: 32-битные числа\n"; *(const char * *)tb_grow(v_lines) = tb_v14060; }
    { const char * tb_v14061 = "// без знака (переполнение по кругу), потом сдвиг; 0 — у самой камеры, 16777215 — далеко\n"; *(const char * *)tb_grow(v_lines) = tb_v14061; }
    { const char * tb_v14062 = "TB_INL uint32_t tb_tri3_depth(const uint32_t *pl, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14062; }
    { const char * tb_v14063 = "    uint32_t k = pl[2] + pl[0] * (uint32_t)(2 * x + 1) + pl[1] * (uint32_t)(2 * y + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v14063; }
    { const char * tb_v14064 = "    int32_t d = (int32_t)k >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v14064; }
    { const char * tb_v14065 = "    return d < 0 ? 0u : d > 16777215 ? 16777215u : (uint32_t)d;\n"; *(const char * *)tb_grow(v_lines) = tb_v14065; }
    { const char * tb_v14066 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14066; }
    { const char * tb_v14067 = "// треугольник с углами в пределах ±8192 (t меняется: порядок углов); pl — плоскость глубины (3D) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v14067; }
    { const char * tb_v14068 = "// gpu, cpu — где рисовать (сетку на видеокарте может считать сама видеокарта: тогда здесь только процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v14068; }
    { const char * tb_v14069 = "// треугольник с картинкой: tb_tex_cur — его запись текстуры (иначе 0). Точка картинки для (x, y):\n"; *(const char * *)tb_grow(v_lines) = tb_v14069; }
    { const char * tb_v14070 = "// W = (2^24 - глубина) >> 4 (это 1/z), u = (плоскость u·W) / W — с перспективой, как на видеокарте (tbt.frag)\n"; *(const char * *)tb_grow(v_lines) = tb_v14070; }
    { const char * tb_v14071 = "TB_API const tb_gtex_t *tb_tex_cur = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14071; }
    { const char * tb_v14072 = "TB_INL long long tb_fdiv(long long a, long long b);\n"; *(const char * *)tb_grow(v_lines) = tb_v14072; }
    { const char * tb_v14073 = "TB_INL int tb_tex_px(const tb_gtex_t *tx, uint32_t d, long long x, long long y, uint32_t *out) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14073; }
    { const char * tb_v14074 = "    long long W = (16777216 - (long long)d) >> 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v14074; }
    { const char * tb_v14075 = "    if (W < 1) W = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14075; }
    { const char * tb_v14076 = "    long long su = (tx->cu + tx->au * (2 * x + 1) + tx->bu * (2 * y + 1)) >> 6, sv = (tx->cv + tx->av * (2 * x + 1) + tx->bv * (2 * y + 1)) >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v14076; }
    { const char * tb_v14077 = "    long long u = tb_fdiv(tb_fdiv(su, W), 16), v = tb_fdiv(tb_fdiv(sv, W), 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v14077; }
    { const char * tb_v14078 = "    u -= tb_fdiv(u, tx->w) * (long long)tx->w;   // повтор картинки: 0…w-1\n"; *(const char * *)tb_grow(v_lines) = tb_v14078; }
    { const char * tb_v14079 = "    v -= tb_fdiv(v, tx->h) * (long long)tx->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v14079; }
    { const char * tb_v14080 = "    *out = tb_imgpx[tx->off + (uint32_t)v * tx->w + (uint32_t)u];\n"; *(const char * *)tb_grow(v_lines) = tb_v14080; }
    { const char * tb_v14081 = "    return (*out >> 24) >= 128;\n"; *(const char * *)tb_grow(v_lines) = tb_v14081; }
    { const char * tb_v14082 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14082; }
    { const char * tb_v14083 = "// точка картинки × оттенок (свет): (т · о + 127) / 255 по каждому цвету\n"; *(const char * *)tb_grow(v_lines) = tb_v14083; }
    { const char * tb_v14084 = "TB_INL uint32_t tb_tex_tint(uint32_t t, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14084; }
    { const char * tb_v14085 = "    uint32_t r = (((t >> 16) & 255) * ((c >> 16) & 255) + 127) / 255, g = (((t >> 8) & 255) * ((c >> 8) & 255) + 127) / 255,\n"; *(const char * *)tb_grow(v_lines) = tb_v14085; }
    { const char * tb_v14086 = "             b = ((t & 255) * (c & 255) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v14086; }
    { const char * tb_v14087 = "    return (c & 0xFF000000u) | (r << 16) | (g << 8) | b;\n"; *(const char * *)tb_grow(v_lines) = tb_v14087; }
    { const char * tb_v14088 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14088; }
    { const char * tb_v14089 = "static void tb_tri_draw_x(long long *t, long long c, const uint32_t *pl, int gpu, int cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14089; }
    { const char * tb_v14090 = "    if (!tb_tri_prep(t)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14090; }
    { const char * tb_v14091 = "    const tb_gtex_t *tx = pl ? tb_tex_cur : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14091; }
    { const char * tb_v14092 = "    if (gpu) { if (tx) tb_gpu_tri3t(t, c, pl, tx); else if (pl) tb_gpu_tri3(t, c, pl); else tb_gpu_triangle(t, c); }\n"; *(const char * *)tb_grow(v_lines) = tb_v14092; }
    { const char * tb_v14093 = "    if (cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14093; }
    { const char * tb_v14094 = "        long long xa = t[0], xb = t[0], ya = t[1], yb = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v14094; }
    { const char * tb_v14095 = "        for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14095; }
    { const char * tb_v14096 = "            if (t[i] < xa) xa = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v14096; }
    { const char * tb_v14097 = "            if (t[i] > xb) xb = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v14097; }
    { const char * tb_v14098 = "            if (t[i + 1] < ya) ya = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v14098; }
    { const char * tb_v14099 = "            if (t[i + 1] > yb) yb = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v14099; }
    { const char * tb_v14100 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14100; }
    { const char * tb_v14101 = "        if (xa < 0) xa = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14101; }
    { const char * tb_v14102 = "        if (ya < 0) ya = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14102; }
    { const char * tb_v14103 = "        if (xb > tb_gw - 1) xb = tb_gw - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14103; }
    { const char * tb_v14104 = "        if (yb > tb_gh - 1) yb = tb_gh - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14104; }
    { const char * tb_v14105 = "        for (long long y = ya; y <= yb; y++)\n"; *(const char * *)tb_grow(v_lines) = tb_v14105; }
    { const char * tb_v14106 = "            for (long long x = xa; x <= xb; x++)\n"; *(const char * *)tb_grow(v_lines) = tb_v14106; }
    { const char * tb_v14107 = "                if (tb_tri_edge(t[0], t[1], t[2], t[3], x, y) && tb_tri_edge(t[2], t[3], t[4], t[5], x, y) &&\n"; *(const char * *)tb_grow(v_lines) = tb_v14107; }
    { const char * tb_v14108 = "                    tb_tri_edge(t[4], t[5], t[0], t[1], x, y)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14108; }
    { const char * tb_v14109 = "                    uint32_t col = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v14109; }
    { const char * tb_v14110 = "                    if (pl) {   // 3D: точка видна, если ближе того, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v14110; }
    { const char * tb_v14111 = "                        uint32_t d = tb_tri3_depth(pl, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v14111; }
    { const char * tb_v14112 = "                        if (d >= tb_zb[y * tb_gw + x]) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v14112; }
    { const char * tb_v14113 = "                        if (tx) {   // картинка: прозрачная точка (меньше 128) — дырка, глубину не пишет\n"; *(const char * *)tb_grow(v_lines) = tb_v14113; }
    { const char * tb_v14114 = "                            uint32_t tp;\n"; *(const char * *)tb_grow(v_lines) = tb_v14114; }
    { const char * tb_v14115 = "                            if (!tb_tex_px(tx, d, x, y, &tp)) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v14115; }
    { const char * tb_v14116 = "                            col = tb_tex_tint(tp, col);\n"; *(const char * *)tb_grow(v_lines) = tb_v14116; }
    { const char * tb_v14117 = "                        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14117; }
    { const char * tb_v14118 = "                        tb_zb[y * tb_gw + x] = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v14118; }
    { const char * tb_v14119 = "                    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14119; }
    { const char * tb_v14120 = "                    tb_px[y * tb_gw + x] = col;\n"; *(const char * *)tb_grow(v_lines) = tb_v14120; }
    { const char * tb_v14121 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v14121; }
    { const char * tb_v14122 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14122; }
    { const char * tb_v14123 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14123; }
    { const char * tb_v14124 = "static void tb_tri_draw_i(long long *t, long long c, const uint32_t *pl) { tb_tri_draw_x(t, c, pl, tb_gpu_on, TB_CPU_DRAW); }\n"; *(const char * *)tb_grow(v_lines) = tb_v14124; }
    { const char * tb_v14125 = "// многоугольник с углами-дробями (3D после проекции, огромные треугольники): обрезаем рамкой\n"; *(const char * *)tb_grow(v_lines) = tb_v14125; }
    { const char * tb_v14126 = "// вокруг окна (±2048 точек, но не дальше ±8192), углы округляем, режем веером из первого угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v14126; }
    { const char * tb_v14127 = "// Общие углы округляются одинаково, поэтому соседние треугольники стыкуются без щелей\n"; *(const char * *)tb_grow(v_lines) = tb_v14127; }
    { const char * tb_v14128 = "// округление до ближайшего целого (половина — вверх); быстрее llround, одно и то же везде\n"; *(const char * *)tb_grow(v_lines) = tb_v14128; }
    { const char * tb_v14129 = "TB_INL long long tb_rnd(double x) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14129; }
    { const char * tb_v14130 = "    long long r = (long long)(x + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v14130; }
    { const char * tb_v14131 = "    if ((double)r > x + 0.5) r--;\n"; *(const char * *)tb_grow(v_lines) = tb_v14131; }
    { const char * tb_v14132 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v14132; }
    { const char * tb_v14133 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14133; }
    { const char * tb_v14134 = "static void tb_poly_draw(double *px, double *py, int n, long long c, const uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14134; }
    { const char * tb_v14135 = "    double gx0 = -2048, gy0 = -2048, gx1 = tb_gw + 2048.0, gy1 = tb_gh + 2048.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14135; }
    { const char * tb_v14136 = "    if (gx1 > 8192) gx1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v14136; }
    { const char * tb_v14137 = "    if (gy1 > 8192) gy1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v14137; }
    { const char * tb_v14138 = "    double ax[16], ay[16], bx[16], by[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v14138; }
    { const char * tb_v14139 = "    for (int i = 0; i < n; i++) { ax[i] = px[i]; ay[i] = py[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14139; }
    { const char * tb_v14140 = "    for (int side = 0; side < 4 && n > 0; side++) {   // Сазерленд — Ходжман: по одной стороне рамки\n"; *(const char * *)tb_grow(v_lines) = tb_v14140; }
    { const char * tb_v14141 = "        int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14141; }
    { const char * tb_v14142 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14142; }
    { const char * tb_v14143 = "            int j = (i + 1) % n;\n"; *(const char * *)tb_grow(v_lines) = tb_v14143; }
    { const char * tb_v14144 = "            double vi = side == 0 ? ax[i] - gx0 : side == 1 ? gx1 - ax[i] : side == 2 ? ay[i] - gy0 : gy1 - ay[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v14144; }
    { const char * tb_v14145 = "            double vj = side == 0 ? ax[j] - gx0 : side == 1 ? gx1 - ax[j] : side == 2 ? ay[j] - gy0 : gy1 - ay[j];\n"; *(const char * *)tb_grow(v_lines) = tb_v14145; }
    { const char * tb_v14146 = "            if (vi >= 0) { bx[m] = ax[i]; by[m] = ay[i]; m++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14146; }
    { const char * tb_v14147 = "            if ((vi >= 0) != (vj >= 0)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14147; }
    { const char * tb_v14148 = "                double k = vi / (vi - vj);\n"; *(const char * *)tb_grow(v_lines) = tb_v14148; }
    { const char * tb_v14149 = "                bx[m] = ax[i] + (ax[j] - ax[i]) * k; by[m] = ay[i] + (ay[j] - ay[i]) * k; m++;\n"; *(const char * *)tb_grow(v_lines) = tb_v14149; }
    { const char * tb_v14150 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v14150; }
    { const char * tb_v14151 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14151; }
    { const char * tb_v14152 = "        n = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v14152; }
