    { const char * tb_v14158 = "    for (int i = 1; i + 1 < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14158; }
    { const char * tb_v14159 = "        long long t[6] = { rx[0], ry[0], rx[i], ry[i], rx[i + 1], ry[i + 1] };\n"; *(const char * *)tb_grow(v_lines) = tb_v14159; }
    { const char * tb_v14160 = "        tb_tri_draw_i(t, c, pl);\n"; *(const char * *)tb_grow(v_lines) = tb_v14160; }
