    { const char * tb_v14417 = "    if (!(l > 1e-12)) { tb_lamb = -1; tb_amb0 = amb > 0 ? (amb < 1 ? amb : 1) : 0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14417; }
    { const char * tb_v14418 = "    tb_lt[0] = dx / l; tb_lt[1] = dy / l; tb_lt[2] = dz / l;\n"; *(const char * *)tb_grow(v_lines) = tb_v14418; }
