    { const char * tb_v14505 = "    tb_tex_plane_i(a, b, c, su, pu); tb_tex_plane_i(a, b, c, sv, pv);\n"; *(const char * *)tb_grow(v_lines) = tb_v14505; }
    { const char * tb_v14506 = "    tx->au = pu[0]; tx->bu = pu[1]; tx->cu = pu[2]; tx->av = pv[0]; tx->bv = pv[1]; tx->cv = pv[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v14506; }
    { const char * tb_v14507 = "    tx->off = im->off; tx->w = (uint32_t)im->w; tx->h = (uint32_t)im->h; tx->pad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14507; }
    { const char * tb_v14508 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14508; }
    { const char * tb_v14509 = "// то же в дробях (старый путь): углы (x, y, D) после проекции и (u, v) каждого угла\n"; *(const char * *)tb_grow(v_lines) = tb_v14509; }
    { const char * tb_v14510 = "static void tb_tex_rec_d(const tb_mesh *m, int n, const double *sx, const double *sy, const double *dd, const double *uu, const double *vv, tb_gtex_t *tx) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14510; }
