    { const char * tb_v14513 = "    for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14513; }
    { const char * tb_v14514 = "        double W = floor((16777216 - dd[i]) / 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v14514; }
