    { const char * tb_v14536 = "    tx->off = im->off; tx->w = (uint32_t)im->w; tx->h = (uint32_t)im->h; tx->pad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14536; }
    { const char * tb_v14537 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14537; }
    { const char * tb_v14538 = "// R — поворот сетки (3 × 3): угол p в мире = R p + (x, y, z)\n"; *(const char * *)tb_grow(v_lines) = tb_v14538; }
