    { const char * tb_v14634 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14634; }
    { const char * tb_v14635 = "// фокус экрана × 256 (угол обзора 60°)\n"; *(const char * *)tb_grow(v_lines) = tb_v14635; }
    { const char * tb_v14636 = "TB_INL long long tb_m3_f(void) { return tb_rnd(tb_gh / 2.0 / tan(30 * 3.14159265358979323846 / 180) * 256); }\n"; *(const char * *)tb_grow(v_lines) = tb_v14636; }
    { const char * tb_v14637 = "// угол сетки p (× 4096) по записи r: место на экране (целые точки) и глубина D = 2^24 - 2^24 * zn / z, zn = 205 / 4096\n"; *(const char * *)tb_grow(v_lines) = tb_v14637; }
    { const char * tb_v14638 = "TB_INL void tb_m3_corner(const int32_t *r, const int32_t *p, long long f, long long *o) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14638; }
    { const char * tb_v14639 = "    long long c[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v14639; }
    { const char * tb_v14640 = "    for (int k = 0; k < 3; k++)\n"; *(const char * *)tb_grow(v_lines) = tb_v14640; }
    { const char * tb_v14641 = "        c[k] = (((long long)r[4 * k] * p[0] + (long long)r[4 * k + 1] * p[1] + (long long)r[4 * k + 2] * p[2]) >> 30) + r[4 * k + 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v14641; }
    { const char * tb_v14642 = "    o[0] = ((long long)tb_gw * 128 + tb_fdiv(f * c[0], c[2]) + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v14642; }
    { const char * tb_v14643 = "    o[1] = ((long long)tb_gh * 128 - tb_fdiv(f * c[1], c[2]) + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v14643; }
