    { const char * tb_v14660 = "// закрытая сетка (каждая сторона треугольника есть и в обратную сторону у соседа): грань, повёрнутая\n"; *(const char * *)tb_grow(v_lines) = tb_v14660; }
    { const char * tb_v14661 = "// от камеры, всегда закрыта другими гранями — и у куба снаружи, и у комнаты изнутри (грани внутрь).\n"; *(const char * *)tb_grow(v_lines) = tb_v14661; }
    { const char * tb_v14662 = "// Повёрнута от камеры = на экране по часовой стрелке (площадь < 0). 0 — рисовать все, -1 — пропускать такие\n"; *(const char * *)tb_grow(v_lines) = tb_v14662; }
    { const char * tb_v14663 = "static int tb_cmp_u64(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14663; }
    { const char * tb_v14664 = "    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v14664; }
    { const char * tb_v14665 = "    return x < y ? -1 : x > y;\n"; *(const char * *)tb_grow(v_lines) = tb_v14665; }
    { const char * tb_v14666 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14666; }
    { const char * tb_v14667 = "static int tb_mesh_cull(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14667; }
    { const char * tb_v14668 = "    if (m->cullok) return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v14668; }
    { const char * tb_v14669 = "    m->cullok = 1; m->cull = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14669; }
    { const char * tb_v14670 = "    long long ne = 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v14670; }
    { const char * tb_v14671 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v14671; }
    { const char * tb_v14672 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14672; }
    { const char * tb_v14673 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14673; }
    { const char * tb_v14674 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v14674; }
    { const char * tb_v14675 = "        for (int k = 0; k < 3; k++) e[3 * t + k] = ((uint64_t)ti[k] << 32) | ti[(k + 1) % 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v14675; }
    { const char * tb_v14676 = "        const double *p = m->v + 3 * ti[0], *q = m->v + 3 * ti[1], *r = m->v + 3 * ti[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v14676; }
    { const char * tb_v14677 = "        vol += p[0] * (q[1] * r[2] - q[2] * r[1]) + p[1] * (q[2] * r[0] - q[0] * r[2]) + p[2] * (q[0] * r[1] - q[1] * r[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v14677; }
    { const char * tb_v14678 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14678; }
    { const char * tb_v14679 = "    qsort(e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64);\n"; *(const char * *)tb_grow(v_lines) = tb_v14679; }
    { const char * tb_v14680 = "    int closed = ne > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14680; }
    { const char * tb_v14681 = "    for (long long i = 0; i < ne && closed; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14681; }
    { const char * tb_v14682 = "        if (i + 1 < ne && e[i] == e[i + 1]) closed = 0;   // одна сторона дважды в одну сторону\n"; *(const char * *)tb_grow(v_lines) = tb_v14682; }
    { const char * tb_v14683 = "        uint64_t back = (e[i] << 32) | (e[i] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v14683; }
    { const char * tb_v14684 = "        if ((uint32_t)e[i] == (uint32_t)(e[i] >> 32) || !bsearch(&back, e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64)) closed = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14684; }
    { const char * tb_v14685 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14685; }
    { const char * tb_v14686 = "    free(e);\n"; *(const char * *)tb_grow(v_lines) = tb_v14686; }
    { const char * tb_v14687 = "    if (closed && fabs(vol) > 1e-12) m->cull = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14687; }
    { const char * tb_v14688 = "    return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v14688; }
    { const char * tb_v14689 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14689; }
    { const char * tb_v14690 = "// сетки для видеокарты: у каждой сначала углы (x, y, z, 0), потом треугольники по две строки:\n"; *(const char * *)tb_grow(v_lines) = tb_v14690; }
    { const char * tb_v14691 = "// (номера углов, цвет) и (нормаль × 2^14, -1)\n"; *(const char * *)tb_grow(v_lines) = tb_v14691; }
    { const char * tb_v14692 = "TB_API long long tb_mesh_pack(int32_t *dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14692; }
