    { const char * tb_v14708 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14708; }
    { const char * tb_v14709 = "        at += m->nv + 2 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v14709; }
