    { const char * tb_v14711 = "    return at;\n"; *(const char * *)tb_grow(v_lines) = tb_v14711; }
    { const char * tb_v14712 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14712; }
    { const char * tb_v14713 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14713; }
