    { const char * tb_v14926 = "    double f = tb_gh / 2.0 / tan(30 * 3.14159265358979323846 / 180);\n"; *(const char * *)tb_grow(v_lines) = tb_v14926; }
    { const char * tb_v14927 = "    int st = tb_m3_test(m->bs, M, T, f, m->big);\n"; *(const char * *)tb_grow(v_lines) = tb_v14927; }
    { const char * tb_v14928 = "    if (st == 0) return;   // вся сетка за камерой или вне экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v14928; }
