    { const char * tb_v14936 = "    for (int k = 0; k < 3; k++) go.rec.r[12 + k] = (int32_t)tb_rnd((R[0][k] * tb_lt[0] + R[1][k] * tb_lt[1] + R[2][k] * tb_lt[2]) * 16384);\n"; *(const char * *)tb_grow(v_lines) = tb_v14936; }
    { const char * tb_v14937 = "    go.rec.r[15] = tb_lamb;\n"; *(const char * *)tb_grow(v_lines) = tb_v14937; }
    { const char * tb_v14938 = "    const int32_t *L = go.rec.r + 12;\n"; *(const char * *)tb_grow(v_lines) = tb_v14938; }
