    { const char * tb_v14940 = "    if (m->nch <= 1) { tb_draw_mesh_d(m, x, y, z, R, L, 0, m->n); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14940; }
    { const char * tb_v14941 = "    // сетка большая и задевает камеру или край: по кускам — дальние на видеокарте, ближние старым путём\n"; *(const char * *)tb_grow(v_lines) = tb_v14941; }
    { const char * tb_v14942 = "    for (long long c = 0; c < m->nch; c++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14942; }
