    { const char * tb_v14948 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14948; }
    { const char * tb_v14949 = "// ======== 3D (1.3): свет по углам, лампы, туман, тени, прозрачность, кости ========\n"; *(const char * *)tb_grow(v_lines) = tb_v14949; }
    { const char * tb_v14950 = "// Сетка с этими вещами считается на процессоре дробями: кости, место каждого угла в мире, свет каждого угла\n"; *(const char * *)tb_grow(v_lines) = tb_v14950; }
    { const char * tb_v14951 = "// (солнце, лампы, блик), место в тени, обрезка у камеры и рамкой вокруг окна. А точки внутри треугольника —\n"; *(const char * *)tb_grow(v_lines) = tb_v14951; }
    { const char * tb_v14952 = "// целыми числами одной формулой и на процессоре (tb_lit_px), и на видеокарте (tbl.frag, tb_fragl в tb3.metal):\n"; *(const char * *)tb_grow(v_lines) = tb_v14952; }
    { const char * tb_v14953 = "// значение в точке = (e0·v0·W0 + e1·v1·W1 + e2·v2·W2) / (e0·W0 + e1·W1 + e2·W2), где e — те же «стороны», что решают,\n"; *(const char * *)tb_grow(v_lines) = tb_v14953; }
    { const char * tb_v14954 = "// внутри ли точка (tb_tri_edge), а W — 1/z угла (так свет и тени ложатся с перспективой). Кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v14954; }
    { const char * tb_v14955 = "TB_INL double tb_fmin(double a, double b) { return a < b ? a : b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14955; }
    { const char * tb_v14956 = "TB_INL double tb_fmax(double a, double b) { return a > b ? a : b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14956; }
    { const char * tb_v14957 = "typedef struct { int on, spot; double p[3], d[3], c0, c1, range, col[3]; } tb_lamp_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v14957; }
    { const char * tb_v14958 = "TB_API tb_lamp_t tb_lamps[8];\n"; *(const char * *)tb_grow(v_lines) = tb_v14958; }
