    { const char * tb_v14965 = "TB_API uint32_t *tb_sm = 0;              // карта теней (процессор): глубина от солнца, 0…65535\n"; *(const char * *)tb_grow(v_lines) = tb_v14965; }
    { const char * tb_v14966 = "TB_API long long tb_sm_ver = 0;          // номер карты (растёт при каждой новой)\n"; *(const char * *)tb_grow(v_lines) = tb_v14966; }
    { const char * tb_v14967 = "TB_API int tb_sm_live = 0;               // карта этой сцены готова: треугольники сцены знают про тени\n"; *(const char * *)tb_grow(v_lines) = tb_v14967; }
    { const char * tb_v14968 = "TB_API double tb_smC[3], tb_smR[3], tb_smU[3], tb_smF[3], tb_smT;   // квадрат теней: центр, оси, размер точки карты\n"; *(const char * *)tb_grow(v_lines) = tb_v14968; }
    { const char * tb_v14969 = "// видеокарта: какая карта теней лежит в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v14969; }
    { const char * tb_v14970 = "TB_API long long tb_gsm_batch = -1, tb_gsm_ver = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14970; }
