    { const char * tb_v15991 = "static double tb_sh_t0 = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v15991; }
    { const char * tb_v15992 = "// углы сетки по порядку треугольников: место 3, нормаль 3, цвет 4, (u, v) 2, касательная 3 (куда растёт u), 1 пусто,\n"; *(const char * *)tb_grow(v_lines) = tb_v15992; }
