    { const char * tb_v16412 = "        id g = TB_MSG(id, c, \"extendedGamepad\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16412; }
    { const char * tb_v16413 = "        if (!g) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v16413; }
