    { const char * tb_v16415 = "        p->on = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16415; }
    { const char * tb_v16416 = "        static const char *bn[TB_PB_N] = { \"buttonA\", \"buttonB\", \"buttonX\", \"buttonY\", \"leftShoulder\", \"rightShoulder\",\n"; *(const char * *)tb_grow(v_lines) = tb_v16416; }
    { const char * tb_v16417 = "            \"leftTrigger\", \"rightTrigger\", \"leftThumbstickButton\", \"rightThumbstickButton\", \"buttonMenu\", \"buttonOptions\", \"buttonHome\", 0, 0, 0, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v16417; }
    { const char * tb_v16418 = "        for (int k = 0; k < TB_PB_N; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16418; }
    { const char * tb_v16419 = "            if (!bn[k]) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v16419; }
