    { const char * tb_v16466 = "TB_API int tb_pad_fd[TB_PADS] = { -1, -1, -1, -1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v16466; }
    { const char * tb_v16467 = "TB_API long long tb_pad_look = -100000;\n"; *(const char * *)tb_grow(v_lines) = tb_v16467; }
    { const char * tb_v16468 = "TB_API void tb_pad_poll(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16468; }
    { const char * tb_v16469 = "    // новые геймпады ищем раз в 2 секунды\n"; *(const char * *)tb_grow(v_lines) = tb_v16469; }
    { const char * tb_v16470 = "    long long now = tb_time_ms();\n"; *(const char * *)tb_grow(v_lines) = tb_v16470; }
