    { const char * tb_v16615 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16615; }
    { const char * tb_v16616 = "// точка между кадрами звука: кривая Эрмита по 4 соседям (чище, чем прямая между двумя)\n"; *(const char * *)tb_grow(v_lines) = tb_v16616; }
    { const char * tb_v16617 = "TB_INL float tb_sread(const tb_snd *s, double p, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16617; }
    { const char * tb_v16618 = "    double fl = floor(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v16618; }
    { const char * tb_v16619 = "    long long i = (long long)fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v16619; }
    { const char * tb_v16620 = "    float t = (float)(p - fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v16620; }
    { const char * tb_v16621 = "    float a = tb_sget(s, i - 1, c, loop), b = tb_sget(s, i, c, loop), cc = tb_sget(s, i + 1, c, loop), d = tb_sget(s, i + 2, c, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v16621; }
    { const char * tb_v16622 = "    float c1 = 0.5f * (cc - a), c2 = a - 2.5f * b + 2 * cc - 0.5f * d, c3 = 0.5f * (d - a) + 1.5f * (b - cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v16622; }
    { const char * tb_v16623 = "    return ((c3 * t + c2) * t + c1) * t + b;\n"; *(const char * *)tb_grow(v_lines) = tb_v16623; }
    { const char * tb_v16624 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16624; }
    { const char * tb_v16625 = "TB_INL float tb_smono(const tb_snd *s, double p, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16625; }
    { const char * tb_v16626 = "    if (s->ch > 1) return 0.5f * (tb_sread(s, p, 0, loop) + tb_sread(s, p, 1, loop));\n"; *(const char * *)tb_grow(v_lines) = tb_v16626; }
    { const char * tb_v16627 = "    return tb_sread(s, p, 0, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v16627; }
    { const char * tb_v16628 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16628; }
    { const char * tb_v16629 = "// голос кончился: временный звук (play_tone) больше не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v16629; }
    { const char * tb_v16630 = "static void tb_voice_end(tb_voice *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16630; }
    { const char * tb_v16631 = "    v->on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16631; }
    { const char * tb_v16632 = "    tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v16632; }
    { const char * tb_v16633 = "    if (s->temp && s->d) { free(s->d); s->d = 0; s->n = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16633; }
    { const char * tb_v16634 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16634; }
    { const char * tb_v16635 = "// куда и как громко слышен 3D-голос: громкость ушей, задержка ушей, фильтры, Доплер\n"; *(const char * *)tb_grow(v_lines) = tb_v16635; }
    { const char * tb_v16636 = "static void tb_voice_3d(tb_voice *v, float *tl, float *tr, double *tdl, double *tdr, float *fl, float *fr) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16636; }
    { const char * tb_v16637 = "    double dx = v->x - tb_lis[0], dy = v->y - tb_lis[1], dz = v->z - tb_lis[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v16637; }
    { const char * tb_v16638 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v16638; }
    { const char * tb_v16639 = "    double side = 0, front = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16639; }
    { const char * tb_v16640 = "    if (d > 1e-9) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16640; }
    { const char * tb_v16641 = "        side = (dx * tb_lis[3] + dy * tb_lis[4] + dz * tb_lis[5]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v16641; }
    { const char * tb_v16642 = "        front = (dx * tb_lis[6] + dy * tb_lis[7] + dz * tb_lis[8]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v16642; }
    { const char * tb_v16643 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16643; }
    { const char * tb_v16644 = "    if (d < 0.25) { side *= d / 0.25; front = 1; }   // звук «в голове» — по центру\n"; *(const char * *)tb_grow(v_lines) = tb_v16644; }
    { const char * tb_v16645 = "    double g = d <= 1 ? 1 : 1 / d;                    // громкость падает с расстоянием\n"; *(const char * *)tb_grow(v_lines) = tb_v16645; }
    { const char * tb_v16646 = "    double a = (side + 1) * 0.7853981633974483;      // стороны с равной мощностью\n"; *(const char * *)tb_grow(v_lines) = tb_v16646; }
    { const char * tb_v16647 = "    *tl = (float)(v->vol * g * cos(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v16647; }
    { const char * tb_v16648 = "    *tr = (float)(v->vol * g * sin(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v16648; }
    { const char * tb_v16649 = "    double itd = 0.00066 * TB_SR * fabs(side);        // до 0,66 мс между ушами\n"; *(const char * *)tb_grow(v_lines) = tb_v16649; }
    { const char * tb_v16650 = "    *tdl = side > 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16650; }
    { const char * tb_v16651 = "    *tdr = side < 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16651; }
    { const char * tb_v16652 = "    double fc = 20000 / (1 + d * 0.03);               // воздух: далёкие звуки глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v16652; }
    { const char * tb_v16653 = "    if (front < 0) fc *= 1 - 0.35 * -front;           // сзади глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v16653; }
    { const char * tb_v16654 = "    double fs = fc * (1 - 0.65 * fabs(side));         // дальнее ухо в тени головы\n"; *(const char * *)tb_grow(v_lines) = tb_v16654; }
    { const char * tb_v16655 = "    double cl = side > 0 ? fs : fc, cr = side < 0 ? fs : fc;\n"; *(const char * *)tb_grow(v_lines) = tb_v16655; }
    { const char * tb_v16656 = "    *fl = (float)(1 - exp(-6.283185307179586 * cl / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v16656; }
    { const char * tb_v16657 = "    *fr = (float)(1 - exp(-6.283185307179586 * cr / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v16657; }
    { const char * tb_v16658 = "    // Доплер: как быстро звук приближается (расстояние за блок 10 мс), звук летит 343 ед/с\n"; *(const char * *)tb_grow(v_lines) = tb_v16658; }
    { const char * tb_v16659 = "    double want = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16659; }
    { const char * tb_v16660 = "    if (!v->fresh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16660; }
    { const char * tb_v16661 = "        double sp = (d - v->lastd) * TB_SR / TB_SBLOCK;\n"; *(const char * *)tb_grow(v_lines) = tb_v16661; }
    { const char * tb_v16662 = "        if (fabs(sp) < 686) want = 343 / (343 + sp);   // быстрее — это прыжок, не движение\n"; *(const char * *)tb_grow(v_lines) = tb_v16662; }
    { const char * tb_v16663 = "        if (want < 0.5) want = 0.5;\n"; *(const char * *)tb_grow(v_lines) = tb_v16663; }
    { const char * tb_v16664 = "        if (want > 2) want = 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v16664; }
    { const char * tb_v16665 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16665; }
    { const char * tb_v16666 = "    v->dop = v->fresh ? 1 : v->dop * 0.8 + want * 0.2;\n"; *(const char * *)tb_grow(v_lines) = tb_v16666; }
    { const char * tb_v16667 = "    v->lastd = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v16667; }
    { const char * tb_v16668 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16668; }
    { const char * tb_v16669 = "// смешать n кадров всех голосов в out (стерео, по очереди лево-право)\n"; *(const char * *)tb_grow(v_lines) = tb_v16669; }
    { const char * tb_v16670 = "static void tb_mix(float *out, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16670; }
    { const char * tb_v16671 = "    memset(out, 0, sizeof(float) * 2 * (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v16671; }
    { const char * tb_v16672 = "    pthread_mutex_lock(&tb_slock);\n"; *(const char * *)tb_grow(v_lines) = tb_v16672; }
    { const char * tb_v16673 = "    for (int k = 0; k < TB_NVOICE; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16673; }
    { const char * tb_v16674 = "        tb_voice *v = &tb_voices[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v16674; }
    { const char * tb_v16675 = "        if (!v->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v16675; }
    { const char * tb_v16676 = "        tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v16676; }
    { const char * tb_v16677 = "        if (!s->d || s->n == 0) { tb_voice_end(v); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16677; }
    { const char * tb_v16678 = "        float tl = (float)v->vol, tr = (float)v->vol, al = 1, ar = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16678; }
    { const char * tb_v16679 = "        double tdl = 0, tdr = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16679; }
    { const char * tb_v16680 = "        if (v->is3d) tb_voice_3d(v, &tl, &tr, &tdl, &tdr, &al, &ar);\n"; *(const char * *)tb_grow(v_lines) = tb_v16680; }
    { const char * tb_v16681 = "        if (v->stop) { tl = 0; tr = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16681; }
    { const char * tb_v16682 = "        if (v->fresh) { v->gl = tl; v->gr = tr; v->dl = tdl; v->dr = tdr; v->fresh = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16682; }
    { const char * tb_v16683 = "        double step = s->rate / TB_SR * v->pitch * (v->is3d ? v->dop : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v16683; }
    { const char * tb_v16684 = "        float gl = v->gl, gr = v->gr, dgl = (tl - gl) / n, dgr = (tr - gr) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v16684; }
    { const char * tb_v16685 = "        double dl = v->dl, dr = v->dr, ddl = (tdl - dl) / n, ddr = (tdr - dr) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v16685; }
    { const char * tb_v16686 = "        int done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16686; }
    { const char * tb_v16687 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16687; }
    { const char * tb_v16688 = "            float l, r;\n"; *(const char * *)tb_grow(v_lines) = tb_v16688; }
    { const char * tb_v16689 = "            if (v->is3d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16689; }
    { const char * tb_v16690 = "                l = tb_smono(s, v->pos - dl * step, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v16690; }
    { const char * tb_v16691 = "                r = tb_smono(s, v->pos - dr * step, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v16691; }
    { const char * tb_v16692 = "                v->lpl += al * (l - v->lpl);\n"; *(const char * *)tb_grow(v_lines) = tb_v16692; }
    { const char * tb_v16693 = "                v->lpr += ar * (r - v->lpr);\n"; *(const char * *)tb_grow(v_lines) = tb_v16693; }
    { const char * tb_v16694 = "                l = v->lpl;\n"; *(const char * *)tb_grow(v_lines) = tb_v16694; }
    { const char * tb_v16695 = "                r = v->lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v16695; }
    { const char * tb_v16696 = "            } else if (s->ch > 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16696; }
    { const char * tb_v16697 = "                l = tb_sread(s, v->pos, 0, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v16697; }
    { const char * tb_v16698 = "                r = tb_sread(s, v->pos, 1, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v16698; }
    { const char * tb_v16699 = "            } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v16699; }
    { const char * tb_v16700 = "                l = r = tb_sread(s, v->pos, 0, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v16700; }
    { const char * tb_v16701 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v16701; }
    { const char * tb_v16702 = "            out[2 * i] += l * gl;\n"; *(const char * *)tb_grow(v_lines) = tb_v16702; }
    { const char * tb_v16703 = "            out[2 * i + 1] += r * gr;\n"; *(const char * *)tb_grow(v_lines) = tb_v16703; }
    { const char * tb_v16704 = "            gl += dgl; gr += dgr; dl += ddl; dr += ddr;\n"; *(const char * *)tb_grow(v_lines) = tb_v16704; }
    { const char * tb_v16705 = "            v->pos += step;\n"; *(const char * *)tb_grow(v_lines) = tb_v16705; }
    { const char * tb_v16706 = "            if (v->pos >= (double)s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16706; }
    { const char * tb_v16707 = "                if (v->loop) v->pos -= (double)s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v16707; }
    { const char * tb_v16708 = "                else { done = 1; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16708; }
    { const char * tb_v16709 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v16709; }
    { const char * tb_v16710 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v16710; }
    { const char * tb_v16711 = "        v->gl = tl; v->gr = tr; v->dl = tdl; v->dr = tdr;\n"; *(const char * *)tb_grow(v_lines) = tb_v16711; }
    { const char * tb_v16712 = "        if (done || v->stop) tb_voice_end(v);\n"; *(const char * *)tb_grow(v_lines) = tb_v16712; }
    { const char * tb_v16713 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16713; }
    { const char * tb_v16714 = "    float mt = (float)tb_master;\n"; *(const char * *)tb_grow(v_lines) = tb_v16714; }
    { const char * tb_v16715 = "    pthread_mutex_unlock(&tb_slock);\n"; *(const char * *)tb_grow(v_lines) = tb_v16715; }
    { const char * tb_v16716 = "    // общая громкость (плавно) и ограничитель: громко — сразу тише, потом медленно назад\n"; *(const char * *)tb_grow(v_lines) = tb_v16716; }
    { const char * tb_v16717 = "    float dm = (mt - tb_mg) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v16717; }
    { const char * tb_v16718 = "    for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16718; }
    { const char * tb_v16719 = "        tb_mg += dm;\n"; *(const char * *)tb_grow(v_lines) = tb_v16719; }
    { const char * tb_v16720 = "        float l = out[2 * i] * tb_mg, r = out[2 * i + 1] * tb_mg;\n"; *(const char * *)tb_grow(v_lines) = tb_v16720; }
    { const char * tb_v16721 = "        float pk = fabsf(l) > fabsf(r) ? fabsf(l) : fabsf(r);\n"; *(const char * *)tb_grow(v_lines) = tb_v16721; }
    { const char * tb_v16722 = "        if (pk * tb_lim > 0.98f) tb_lim = 0.98f / pk;\n"; *(const char * *)tb_grow(v_lines) = tb_v16722; }
    { const char * tb_v16723 = "        else tb_lim += (1 - tb_lim) * 0.0002f;\n"; *(const char * *)tb_grow(v_lines) = tb_v16723; }
    { const char * tb_v16724 = "        l *= tb_lim; r *= tb_lim;\n"; *(const char * *)tb_grow(v_lines) = tb_v16724; }
    { const char * tb_v16725 = "        out[2 * i] = l > 1 ? 1 : l < -1 ? -1 : l;\n"; *(const char * *)tb_grow(v_lines) = tb_v16725; }
    { const char * tb_v16726 = "        out[2 * i + 1] = r > 1 ? 1 : r < -1 ? -1 : r;\n"; *(const char * *)tb_grow(v_lines) = tb_v16726; }
    { const char * tb_v16727 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16727; }
    { const char * tb_v16728 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16728; }
    { const char * tb_v16729 = "static long long tb_snd_now_us(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16729; }
    { const char * tb_v16730 = "    struct timespec ts;\n"; *(const char * *)tb_grow(v_lines) = tb_v16730; }
    { const char * tb_v16731 = "    clock_gettime(CLOCK_MONOTONIC, &ts);\n"; *(const char * *)tb_grow(v_lines) = tb_v16731; }
    { const char * tb_v16732 = "    return (long long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v16732; }
    { const char * tb_v16733 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16733; }
    { const char * tb_v16734 = "// без устройства: время идёт как настоящее, звук — в файл (TB_SOUND_FILE) или никуда\n"; *(const char * *)tb_grow(v_lines) = tb_v16734; }
    { const char * tb_v16735 = "static void tb_snd_paced(FILE *f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16735; }
    { const char * tb_v16736 = "    float buf[TB_SBLOCK * 2];\n"; *(const char * *)tb_grow(v_lines) = tb_v16736; }
    { const char * tb_v16737 = "    short pcm[TB_SBLOCK * 2];\n"; *(const char * *)tb_grow(v_lines) = tb_v16737; }
    { const char * tb_v16738 = "    unsigned long long bytes = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16738; }
    { const char * tb_v16739 = "    long long next = tb_snd_now_us();\n"; *(const char * *)tb_grow(v_lines) = tb_v16739; }
    { const char * tb_v16740 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16740; }
    { const char * tb_v16741 = "        tb_mix(buf, TB_SBLOCK);\n"; *(const char * *)tb_grow(v_lines) = tb_v16741; }
    { const char * tb_v16742 = "        if (f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16742; }
    { const char * tb_v16743 = "            for (int i = 0; i < TB_SBLOCK * 2; i++) pcm[i] = (short)lrintf(buf[i] * 32767);\n"; *(const char * *)tb_grow(v_lines) = tb_v16743; }
    { const char * tb_v16744 = "            fwrite(pcm, sizeof pcm, 1, f);\n"; *(const char * *)tb_grow(v_lines) = tb_v16744; }
    { const char * tb_v16745 = "            bytes += sizeof pcm;\n"; *(const char * *)tb_grow(v_lines) = tb_v16745; }
    { const char * tb_v16746 = "            // заголовок WAV сразу верный: программа может закончиться когда угодно\n"; *(const char * *)tb_grow(v_lines) = tb_v16746; }
    { const char * tb_v16747 = "            unsigned int riff = (unsigned int)(36 + bytes), data = (unsigned int)bytes;\n"; *(const char * *)tb_grow(v_lines) = tb_v16747; }
    { const char * tb_v16748 = "            fseek(f, 4, SEEK_SET); fwrite(&riff, 4, 1, f);\n"; *(const char * *)tb_grow(v_lines) = tb_v16748; }
    { const char * tb_v16749 = "            fseek(f, 40, SEEK_SET); fwrite(&data, 4, 1, f);\n"; *(const char * *)tb_grow(v_lines) = tb_v16749; }
    { const char * tb_v16750 = "            fseek(f, 0, SEEK_END);\n"; *(const char * *)tb_grow(v_lines) = tb_v16750; }
    { const char * tb_v16751 = "            fflush(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v16751; }
    { const char * tb_v16752 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v16752; }
    { const char * tb_v16753 = "        next += 1000000LL * TB_SBLOCK / TB_SR;\n"; *(const char * *)tb_grow(v_lines) = tb_v16753; }
    { const char * tb_v16754 = "        long long wait = next - tb_snd_now_us();\n"; *(const char * *)tb_grow(v_lines) = tb_v16754; }
