    { const char * tb_v16911 = "// WAV: PCM 8/16/24/32 бита или float 32; моно или стерео (больше каналов — берём первые два)\n"; *(const char * *)tb_grow(v_lines) = tb_v16911; }
    { const char * tb_v16912 = "TB_API long long tb_load_sound(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16912; }
    { const char * tb_v16913 = "    FILE *f = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16913; }
    { const char * tb_v16914 = "    if (!f) { tb_err = \"нет такого файла звука\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v16914; }
    { const char * tb_v16915 = "    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v16915; }
