    { const char * tb_v16919 = "    if (sz < 12 || memcmp(b, \"RIFF\", 4) != 0 || memcmp(b + 8, \"WAVE\", 4) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16919; }
    { const char * tb_v16920 = "        tb_err = sz >= 4 && memcmp(b, \"OggS\", 4) == 0 ? \"OGG пока не умею: сохрани звук как WAV\" : \"это не WAV-файл\";\n"; *(const char * *)tb_grow(v_lines) = tb_v16920; }
    { const char * tb_v16921 = "        free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v16921; }
