    { const char * tb_v16932 = "        if (memcmp(b + p, \"fmt \", 4) == 0 && n >= 16) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16932; }
    { const char * tb_v16933 = "            tag = tb_le16(c); ch = tb_le16(c + 2); rate = tb_le32(c + 4); bits = tb_le16(c + 14);\n"; *(const char * *)tb_grow(v_lines) = tb_v16933; }
    { const char * tb_v16934 = "            if (tag == 0xFFFE && n >= 26) tag = tb_le16(c + 24);   // «расширенный» WAV: вид внутри\n"; *(const char * *)tb_grow(v_lines) = tb_v16934; }
    { const char * tb_v16935 = "        } else if (memcmp(b + p, \"data\", 4) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16935; }
