    { const char * tb_v16939 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16939; }
    { const char * tb_v16940 = "    int okf = (tag == 1 && (bits == 8 || bits == 16 || bits == 24 || bits == 32)) || (tag == 3 && (bits == 32 || bits == 64));\n"; *(const char * *)tb_grow(v_lines) = tb_v16940; }
    { const char * tb_v16941 = "    if (!data || !okf || ch == 0 || rate == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16941; }
