    { const char * tb_v17013 = "    if (!d) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v17013; }
    { const char * tb_v17014 = "    long long ramp = TB_SR / 200;\n"; *(const char * *)tb_grow(v_lines) = tb_v17014; }
    { const char * tb_v17015 = "    if (ramp * 2 > n) ramp = n / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v17015; }
    { const char * tb_v17016 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v17016; }
    { const char * tb_v17017 = "        double e = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v17017; }
